import{d as D,C as l,o as N,c as R,a3 as i,E as a,j as t,a as e}from"./chunks/framework.Q4yG9rk_.js";const L=JSON.parse('{"title":"庄子·外物","description":"从外物不可必、利害焚和，到涸辙之鲋、任公子大钓与儒者发冢，辨析结果、救助、行动尺度及言辞与实际行为的关系。","frontmatter":{"title":"庄子·外物","description":"从外物不可必、利害焚和，到涸辙之鲋、任公子大钓与儒者发冢，辨析结果、救助、行动尺度及言辞与实际行为的关系。","category":"guide","aliases":["外物","庄子外物","zhuangzi chapter 26"],"source":["《庄子·杂篇·外物》"]},"headers":[],"relativePath":"daoism/zhuang-zi/chapter-26.md","filePath":"daoism/zhuang-zi/chapter-26.md","lastUpdated":1792641266000}'),E={name:"daoism/zhuang-zi/chapter-26.md"},B=D({...E,setup(G){const p=[{id:"ww_uncertainty_s1",label:"外物不可必：不同人物的遭遇",sentences:[["外物不可必，故龙逢诛，比干戮，箕子狂，恶来死，桀、纣亡。"]]},{id:"ww_uncertainty_s2",label:"忠未必信：伍员与苌弘",sentences:[["人主莫不欲其臣之忠，而忠未必信，故伍员流于江，苌弘死于蜀，"],["藏其血，三年而化为碧。"]]},{id:"ww_uncertainty_s3",label:"孝未必爱：孝己与曾参",sentences:[["人亲莫不欲其子之孝，而孝未必爱，故孝己忧而曾参悲。"]]},{id:"ww_uncertainty_s4",label:"摩与火：自然意象",sentences:[["木与木相摩则然，金与火相守则流，阴阳错行，则天地大骇，"],["于是乎有雷有霆，水中有火，乃焚大槐。"]]},{id:"ww_uncertainty_s5",label:"忧患与悬心：两陷无所逃",sentences:[["有甚忧两陷而无所逃。螴蜳不得成，心若县于天地之间，"],["慰暋沈屯，利害相摩，生火甚多，"]]},{id:"ww_uncertainty_s6",label:"焚和与道尽",sentences:[["众人焚和，月固不胜火，于是乎有僓然而道尽。"]]}],o=[{id:"ww_uncertainty_bi",term:"外物不可必",pinyin:"wài wù bù kě bì",meaning:"必涉及期必、保证等。外物不只指财货，可包括遭遇、他人反应与外在结果。不等于所有外物皆有害，或一切结果都不能影响。"},{id:"ww_uncertainty_people",term:"龙逢、比干、箕子、恶来、桀、纣",pinyin:"lóng féng、bǐ gān、jī zǐ、è lái、jié、zhòu",meaning:"古代人物及相关传说。龙逢通常联系关龙逢；这些人物立场不同，原文并列其遭遇，不意味着各种行为同样正当。具体生平不只据本句复原。"},{id:"ww_uncertainty_wuyuan",term:"伍员流于江、苌弘死于蜀",pinyin:"wǔ yún liú yú jiāng、cháng hóng sǐ yú shǔ",meaning:"伍员即通常所称伍子胥；苌弘见古代记载与传说。原文叙其遭难，具体处死、放逐与死地细节不在此全部坐实。"},{id:"ww_uncertainty_bijade",term:"藏其血，三年而化为碧",pinyin:"cáng qí xuè, sān nián ér huà wéi bì",meaning:"血化碧的神异传说。藏血者原文未明说，不自动补为蜀人，也不作为真实物质变化或忠诚之气的证据。"},{id:"ww_uncertainty_xiao",term:"孝己忧、曾参悲",pinyin:"xiào jǐ yōu、zēng shēn bēi",meaning:"以相关人物写孝而仍受忧悲。孝己身份及遭遇见不同传说；本句不直接说孝己忧死、曾参终身悲伤。"},{id:"ww_uncertainty_ran",term:"相摩则然、阴阳错行、水中有火",pinyin:"xiāng mó zé rán、yīn yáng cuò xíng、shuǐ zhōng yǒu huǒ",meaning:"然联系燃理解；错行、水中有火涉及古代自然观与雷霆意象。可与后文生火对读，不直接等同现代物理说明。"},{id:"ww_uncertainty_liangxian",term:"两陷、螴蜳、县",pinyin:"liǎng xiàn、chén dūn、xuán",meaning:"两陷的两端所指有不同解释；螴蜳涉及忧惧不安，音义依注本统一；县联系悬理解。不把不得成只定为现实事务一概无法完成。"},{id:"ww_uncertainty_weimin",term:"慰暋沈屯",pinyin:"wèi mǐn chén zhūn",meaning:"写不安、昏闷、沉滞等，字义与读音有讨论空间。不强行拆成四级心理损害，也不直接对应现代诊断。"},{id:"ww_uncertainty_yue",term:"月固不胜火、僓然而道尽",pinyin:"yuè gù bù shèng huǒ、tuí rán ér dào jìn",meaning:"月的字形、指义及僓的音义有解释空间。可保留焚和、衰败的方向，不将月固定为虚静心、道尽固定为天性或生理机能彻底消失。"}],h=[{id:"ww_fish_s1",label:"庄周借粮：将来的三百金",sentences:[["庄周家贫，故往贷粟于监河侯。"],["监河侯曰：「诺。我将得邑金，将贷子三百金，可乎？」"]]},{id:"ww_fish_s2",label:"庄周作色：车辙中的鲋鱼",sentences:[["庄周忿然作色曰：「周昨来，有中道而呼者，周顾视车辙，中有鲋鱼焉。"],["周问之曰：『鲋鱼来，子何为者耶？』"]]},{id:"ww_fish_s3",label:"鱼求小水：当前所需",sentences:[["对曰：『我，东海之波臣也。君岂有斗升之水而活我哉！』"]]},{id:"ww_fish_s4",label:"故事中的庄周：许以西江之水",sentences:[["周曰：『诺，我且南游吴越之王，激西江之水而迎子，可乎？』"]]},{id:"ww_fish_s5",label:"鲋鱼作色：枯鱼之肆",sentences:[["鲋鱼忿然作色曰：『吾失我常与，我无所处。"],["我得斗升之水然活耳。君乃言此，曾不如早索我于枯鱼之肆。』」"]]}],g=[{id:"ww_fish_daisu",term:"贷粟、监河侯、邑金",pinyin:"dài sù、jiān hé hóu、yì jīn",meaning:"贷粟为借粮；监河侯是故事中的人物称谓，具体身份不坐实；邑金通常联系封邑收入理解。三百金不直接换算现代金额。"},{id:"ww_fish_fenran",term:"忿然作色",pinyin:"fèn rán zuò sè",meaning:"愤怒而神色改变。庄周与故事中的鱼均作色，构成叙事照应。"},{id:"ww_fish_fu",term:"鲋鱼、东海之波臣",pinyin:"fù yú、dōng hǎi zhī bō chén",meaning:"鲋通常联系鲫鱼理解；波臣写水族身份。按寓言阅读，不以淡水鱼自称东海波臣追求现实物种一致。"},{id:"ww_fish_dousheng",term:"斗升之水、活我",pinyin:"dǒu shēng zhī shuǐ、huó wǒ",meaning:"少量水、使我活。斗升是古代量名，不在此精确换算。写救助所需，不作为现代鱼类救援技术。"},{id:"ww_fish_xijiang",term:"激西江之水",pinyin:"jī xī jiāng zhī shuǐ",meaning:"激涉及引导水流等；西江的具体地理所指有讨论空间，不按现代同名河流直接定位。"},{id:"ww_fish_changyu",term:"常与、枯鱼之肆",pinyin:"cháng yǔ、kū yú zhī sì",meaning:"常与联系平常相与的水等生存条件；肆为店铺。以干鱼铺写救助迟到的后果，不直接说此鱼在正文中已死。"},{id:"ww_fish_zeng",term:"曾不如",pinyin:"zēng bù rú",meaning:"竟不如、还不如等，曾的音读依注本统一。强调当前答复的不合所需。"}],u=[{id:"ww_greatfishing_s1",label:"大钓的准备与等待",sentences:[["任公子为大钩巨缁，五十犗以为饵，蹲乎会稽，投竿东海，"],["旦旦而钓，期年不得鱼。"]]},{id:"ww_greatfishing_s2",label:"大鱼出现：白波若山",sentences:[["已而大鱼食之，牵巨钩，陷没而下骛，扬而奋鬐，"],["白波若山，海水震荡，声侔鬼神，惮赫千里。"]]},{id:"ww_greatfishing_s3",label:"分鱼为腊：广大地区饱食",sentences:[["任公子得若鱼，离而腊之，自制河以东，苍梧已北，莫不厌若鱼者。"]]},{id:"ww_greatfishing_s4",label:"后世传说者：惊而相告",sentences:[["已而后世辁才讽说之徒，皆惊而相告也。"]]},{id:"ww_greatfishing_s5",label:"小钓与小言：方法是否相称",sentences:[["夫揭竿累，趣灌渎，守鲵鲋，其于得大鱼难矣！"],["饰小说以干",{text:"县令",glossary:"ww_greatfishing_xuanling"},"，其于大达亦远矣。"]]},{id:"ww_greatfishing_s6",label:"任氏风俗：经世的反问",sentences:[["是以未尝闻任氏之风俗，其不可与经于世亦远矣！"]]}],m=[{id:"ww_greatfishing_rengongzi",term:"任公子、大钩巨缁",pinyin:"rèn gōng zǐ、dà gōu jù zī",meaning:"寓言中的垂钓者，不坐实历史身份；缁本为黑色，此处联系粗大黑色钓绳。"},{id:"ww_greatfishing_jie",term:"五十犗、蹲乎会稽、期年",pinyin:"wǔ shí jiè、cún hū kuài jī、jī nián",meaning:"犗通常指阉割过的牛等；蹲有踞坐义，音读依注本统一；会稽为古地名；期年为满一年。巨量鱼饵与地理按夸张寓言理解。"},{id:"ww_greatfishing_qi",term:"下骛、奋鬐、声侔、惮赫",pinyin:"xià wù、fèn qí、shēng móu、dàn hè",meaning:"骛为疾行；鬐联系鱼背鳍；侔为相比；惮赫写威势震动，音义依注本统一。不是可操作的捕鱼技术。"},{id:"ww_greatfishing_xi",term:"离而腊之、制河、苍梧已北",pinyin:"lí ér xī zhī、zhì hé、cāng wú yǐ běi",meaning:"分割制成干鱼；腊在此读 xī。制河有异文与地理解释，保留来稿；已联系以。供食范围不作精确地图复原。"},{id:"ww_greatfishing_quancai",term:"辁才讽说之徒",pinyin:"quán cái fěng shuō zhī tú",meaning:"辁才指小才、浅识；讽说涉及诵说、传说等。批评特定传述者，不宣布转述与讲故事都无价值。"},{id:"ww_greatfishing_lei",term:"揭竿累、趣灌渎、守鲵鲋",pinyin:"jiē gān léi、qū guàn dú、shǒu ní fù",meaning:"涉及举竿、钓线与小沟水域；累有文字、音义疑难，最终依底本核对；趣联系趋。鲵鲋在此与大鱼形成对照，不逐一等同现代物种分类。"},{id:"ww_greatfishing_xuanling",term:"饰小说以干县令",pinyin:"shì xiǎo shuō yǐ gān xuán lìng",meaning:"小说指琐细言说，不是现代小说体裁。县令有联系高名、美誉等解释，县可联系悬，不直接译为讨好县官；具体训释仍依注本统一。"},{id:"ww_greatfishing_jingshi",term:"大达、任氏之风俗、经于世",pinyin:"dà dá、rèn shì zhī fēng sú、jīng yú shì",meaning:"涉及广大通达、任氏风范及处置世事等。不只指仕途显达，也不确定任公子、大鱼分别象征某位君主与天下。"}],b=[{id:"ww_tomb_s1",label:"诗礼发冢：大儒询问进度",sentences:[["儒以《诗》、《礼》发冢，大儒胪传曰：「东方作矣，事之何若？」"]]},{id:"ww_tomb_s2",label:"小儒报告：衣物与含珠",sentences:[["小儒曰：「未解裙襦，口中有珠。」"]]},{id:"ww_tomb_s3",label:"故事中的引诗：取珠的说辞",sentences:[["「《诗》固有之曰：『青青之麦，生于陵陂。生不布施，死何含珠为？』"]]},{id:"ww_tomb_s4",label:"具体动作：保护口中珠",sentences:[["接其鬓，压其顪，儒以金椎控其颐，徐别其颊，无伤口中珠。」"]]}],c=[{id:"ww_tomb_fazhong",term:"儒以诗礼发冢、大儒、小儒",pinyin:"rú yǐ shī lǐ fā zhǒng、dà rú、xiǎo rú",meaning:"以经典与儒者身份同掘墓行为形成讽刺。不把寓言中的人物直接等同所有儒者，也不据此认定诗礼只能用于犯罪。"},{id:"ww_tomb_luchuan",term:"胪传、东方作矣",pinyin:"lú chuán、dōng fāng zuò yǐ",meaning:"胪传涉及传语、传声；东方作写天将明等。对话归属与引号划分有版本差异，不作为唯一断句。"},{id:"ww_tomb_qunru",term:"裙襦、口中有珠",pinyin:"qún rú、kǒu zhōng yǒu zhū",meaning:"下裙与短衣、死者口中含珠。与古代丧葬含物习俗相关，不补定具体礼制等级与珠的材质。"},{id:"ww_tomb_lingbei",term:"陵陂、青青之麦",pinyin:"líng bēi、qīng qīng zhī mài",meaning:"陵陂为丘陵坡地等。本段所引诗不见于今本《诗经》，作为故事中的引诗，不指认今本某篇。"},{id:"ww_tomb_hui",term:"接鬓、压顪、金椎、控颐、别颊",pinyin:"jiē bìn、yā huì、jīn chuí、kòng yí、bié jiá",meaning:"涉及鬓发、须毛或颌部及金属器具等，细部训释有差异。正文写损伤死者而保护珠的价值倒置，不作具体操作说明。"},{id:"ww_tomb_wushang",term:"徐、无伤口中珠",pinyin:"xú、wú shāng kǒu zhōng zhū",meaning:"徐为缓慢；谨慎所保护的是珠，构成讽刺收束。不将细心本身当作行为正当的证明。"}],w=[{id:"ww_laolai_s1",label:"弟子描述：操心天下的神情",sentences:[["视若营四海，不知其谁氏之子。"]]},{id:"ww_laolai_s2",label:"老莱子的提醒：去躬矜与容知",sentences:[["丘，去汝躬矜与汝容知，斯为君子矣。"]]},{id:"ww_laolai_s3",label:"眼前与长远：行为后果的责问",sentences:[["夫不忍一世之伤，而骜万世之患。"],["抑固窭邪？亡其略弗及邪？"]]},{id:"ww_laolai_s4",label:"名与隐：誉尧非桀与两忘",sentences:[["相引以名，相结以隐。"],["与其誉尧而非桀，不如两忘而闭其所誉。"]]},{id:"ww_laolai_s5",label:"兴事与自矜：末尾节引",sentences:[["反无非伤也，动无非邪也，圣人踌躇以兴事，以每成功。"],["奈何哉，其载焉终矜尔！"]]}],_=[{id:"ww_laolai_people",term:"老莱子、仲尼",pinyin:"lǎo lái zǐ、zhòng ní",meaning:"本段寓言人物。老莱子的历史身份及与孔子的实际关系不在此坐实，故事中的外貌描写也不作为历史孔子的可靠记录。"},{id:"ww_laolai_ying",term:"视若营四海",pinyin:"shì ruò yíng sì hǎi",meaning:"神情如在经营、谋虑天下，营涉及经营、操心等。是人物塑造，不据此判断一切关心天下者都有自矜。"},{id:"ww_laolai_jinzhi",term:"躬矜、容知",pinyin:"gōng jīn、róng zhì",meaning:"自身的矜持、自夸与外在显露的智巧等。知联系智理解。不直接等于有知识、有自尊便错误。"},{id:"ww_laolai_ao",term:"骜万世之患、窭、亡其略弗及",pinyin:"ào wàn shì zhī huàn、jù、wú qí lüè fú jí",meaning:"骜可联系轻忽、傲视等；窭为贫乏；亡可联系无。句法与略的所指有疑义，可保留对长远后果及谋虑的责问，不证明救助必造成后患。"},{id:"ww_laolai_hui",term:"惠以欢为、中民",pinyin:"huì yǐ huān wéi、zhōng mín",meaning:"来稿提供的词条，未收入本页连续原文。惠以欢为可联系施惠、取悦等理解，中民涉及一般民众等，完整语境补齐后再定释。"},{id:"ww_laolai_yin",term:"相引以名，相结以隐",pinyin:"xiāng yǐn yǐ míng, xiāng jié yǐ yǐn",meaning:"以名牵引、以隐结合等，隐的所指有解释空间。不直接定为所有结合都出于秘密私欲。"},{id:"ww_laolai_liangwang",term:"两忘、闭其所誉",pinyin:"liǎng wàng、bì qí suǒ yù",meaning:"联系誉尧非桀的两端理解，收住对称誉的执著等。不自动等于尧桀行为同样正当，或暴政无需批评。"},{id:"ww_laolai_mei",term:"踌躇以兴事、以每成功、终矜",pinyin:"chóu chú yǐ xīng shì、yǐ měi chéng gōng、zhōng jīn",meaning:"踌躇、每及末句有不同训释，可联系从容、审慎与自矜的反省。不只译为犹豫，也不把每解释成每次保证成功。"}],y=[{id:"ww_turtle_s1",label:"元君梦见被捕之使者",sentences:[["宋元君夜半而梦人被发窥阿门，曰："],["「予自宰路之渊，予为清江使河伯之所，渔者余且得予。」"]]},{id:"ww_turtle_s2",label:"占梦与查问：召余且入朝",sentences:[["元君觉，使人占之，曰：「此神龟也。」"],["君曰：「渔者有余且乎？」左右曰：「有。」"],["君曰：「令余且会朝。」明日，余且朝。"]]},{id:"ww_turtle_s3",label:"献龟：杀与活的犹疑",sentences:[["君曰：「渔何得？」对曰：「且之网得白龟焉，箕圆五尺。」"],["君曰：「献若之龟。」"],["龟至，君再欲杀之，再欲活之。心疑，卜之。"]]},{id:"ww_turtle_s4",label:"卜而杀龟：占验与损害",sentences:[["曰：「杀龟以卜吉。」乃刳龟，七十二钻而无遗生筴。"]]},{id:"ww_turtle_s5",label:"仲尼评神龟：能与不能",sentences:[["仲尼曰：「神龟能见梦于元君，而不能避余且之网；"],["知能七十二钻而无遗囗，不能避刳肠之患。"],["如是则知有所困，神有所不及也。虽有至知，万人谋之。"]]},{id:"ww_turtle_s6",label:"鱼畏鹈鹕：小知与大知",sentences:[["鱼不畏网而畏鹈鹕。去小知而大知明，去善而自善矣。"]]},{id:"ww_turtle_s7",label:"婴儿能言：日常交往的条件",sentences:[["婴儿生，无硕师而能言，与能言者处也。」"]]}],x=[{id:"ww_turtle_people",term:"宋元君、余且",pinyin:"sòng yuán jūn、yú jū",meaning:"故事中的国君与渔者。宋元君通常联系宋元公理解；余且的且读 jū。故事不据此复原准确历史纪事。"},{id:"ww_turtle_pifa",term:"被发、窥阿门、觉",pinyin:"pī fà、kuī ē mén、jué",meaning:"被联系披，披散头发；阿门所指有不同解释；觉指醒来。托梦是神异叙事，不作为现实超自然能力的证明。"},{id:"ww_turtle_shi",term:"宰路之渊、为清江使河伯之所",pinyin:"zǎi lù zhī yuān、wèi qīng jiāng shǐ hé bó zhī suǒ",meaning:"涉及深渊名与替清江出使河伯处所。相关水神与地名按故事语境理解，不强作现代地理定位。"},{id:"ww_turtle_jiyuan",term:"箕圆五尺、献若之龟、再欲",pinyin:"jī yuán wǔ chǐ、xiàn ruò zhī guī、zài yù",meaning:"箕圆的尺寸所指需辨；若为你、你的；再欲写反复或两次意欲等，具体不强定。"},{id:"ww_turtle_kugui",term:"刳龟、七十二钻、筴",pinyin:"kū guī、qī shí èr zuàn、cè",meaning:"刳为剖；钻涉及龟甲占卜操作；筴联系策、占验等。七十二及占验按叙事理解，不证明占卜真实准确。"},{id:"ww_turtle_missing",term:"无遗生筴、无遗囗",pinyin:"wú yí shēng cè、—",meaning:"来稿有文字与呈现问题，囗不作为正常词语定音定释。其他文本常见无遗筴，最终应依选定底本核对；暂把握占验无误与不能自保的对照。"},{id:"ww_turtle_xianmeng",term:"见梦、知有所困、神有所不及",pinyin:"xiàn mèng、zhì yǒu suǒ kùn、shén yǒu suǒ bù jí",meaning:"见联系现；知联系智。写异能、智慧仍受限制，不等于遭害者因不够聪明而应负责。"},{id:"ww_turtle_tihu",term:"至知、万人谋之、鹈鹕",pinyin:"zhì zhì、wàn rén móu zhī、tí hú",meaning:"极高智慧、众人的谋取及捕鱼水鸟。万极言众多，不作准确人数；鱼畏何物是寓言判断，不当作完整动物行为学说明。"},{id:"ww_turtle_zishan",term:"去小知、去善而自善、硕师",pinyin:"qù xiǎo zhì、qù shàn ér zì shàn、shuò shī",meaning:"去小知、去善的具体解释有空间，可联系放下拘限与刻意经营等；硕师为大教师、博学之师。不能据此否定所有学习、善行与教育。"}],q=[{id:"ww_unused_s1",label:"惠子言无用：庄子转问用的判断",sentences:[["惠子谓庄子曰：「子言无用。」"],["庄子曰：「知无用而始可与言用矣。"]]},{id:"ww_unused_s2",label:"容足之地：其余土地能否删除",sentences:[["夫地非不广且大也，人之所用容足耳，"],["然则厕足而垫之致黄泉，人尚有用乎？」"]]},{id:"ww_unused_s3",label:"惠子承认：无用亦为用",sentences:[["惠子曰：「无用。」"],["庄子曰：「然则无用之为用也亦明矣。」"]]}],f=[{id:"ww_unused_yong",term:"子言无用、知无用",pinyin:"zǐ yán wú yòng、zhī wú yòng",meaning:"惠子批评言论无用，原文未明说采用何种效用标准。庄子将问题转向有用与无用的判断，不补定为只谈治国或谋生。"},{id:"ww_unused_rongzu",term:"容足、厕足",pinyin:"róng zú、cè zú",meaning:"容纳双脚、置足或立足等，厕不按现代厕所理解。与周围土地的关系相接，不只谈脚掌面积。"},{id:"ww_unused_dian",term:"垫之致黄泉",pinyin:"diàn zhī zhì huáng quán",meaning:"垫涉及陷、下陷等；通常联系将周围土地挖至地下深处的设想理解。黄泉在此不专指死后世界，具体句法仍依注本辨析。"},{id:"ww_unused_weiyong",term:"无用之为用",pinyin:"wú yòng zhī wéi yòng",meaning:"先前未被计入直接用途的部分，也参与使用条件的成立。不是保证所有被称无用者都有巨大价值。"}],k=[{id:"ww_wandering_s1",label:"能游与不能游",sentences:[["庄子曰：「人有能游，且得不游乎！人而不能游，且得游乎！"]]},{id:"ww_wandering_s2",label:"流遁与决绝：疑难表述",sentences:[["夫流遁之志，决绝之行，噫，其非至知厚德之任与！"],["覆坠而不反，火驰而不顾。"]]},{id:"ww_wandering_s3",label:"君臣与时：至人不留行",sentences:[["虽相与为君臣，时也。易世而无以相贱。故曰：至人不留行焉。"]]},{id:"ww_wandering_s4",label:"古今尺度：顺人而不失己",sentences:[["夫尊古而卑今，学者之流也。"],["且以狶韦氏之流观今之世，夫孰能不波！"],["唯至人乃能游于世而不僻，顺人而不失己。」"]]}],P=[{id:"ww_wandering_you",term:"能游、不能游",pinyin:"néng yóu、bù néng yóu",meaning:"游涉及自在活动、处世等，不只指旅行。不能据此说所有外在处境都同样自由。"},{id:"ww_wandering_liudun",term:"流遁之志、决绝之行、其非至知厚德之任与",pinyin:"liú dùn zhī zhì、jué jué zhī xíng、qí fēi zhì zhì hòu dé zhī rèn yú",meaning:"涉及流遁、断绝与知德之任，非及与的语气有不同解释。不把这组句子确定为全面反对隐逸的宣言。"},{id:"ww_wandering_fuzhui",term:"覆坠而不反、火驰而不顾",pinyin:"fù zhuì ér bù fǎn、huǒ chí ér bù gù",meaning:"倾覆、坠落与如火急驰等，具体所指有解释空间。不仅定为某类政治人物或心理状态。"},{id:"ww_wandering_yishi",term:"时、易世、不留行",pinyin:"shí、yì shì、bù liú xíng",meaning:"君臣关系与时势相接，易世写时世变化；不留行可联系不滞固定行迹。不等于现实身份与权力差异不存在。"},{id:"ww_wandering_xiwei",term:"尊古而卑今、狶韦氏、波",pinyin:"zūn gǔ ér bēi jīn、xī wéi shì、bō",meaning:"批评以古贬今的方式；狶韦氏为传说古人，音义依注本统一；波写波荡。不否定所有古代学习，也不宣称当下必胜于古代。"},{id:"ww_wandering_shunren",term:"不僻、顺人而不失己",pinyin:"bù pì、shùn rén ér bù shī jǐ",meaning:"不偏、与人相顺而不丧失自身等。顺不等于无条件服从，不失己也不等于每项旧意见永不修正。"}],z=[{id:"ww_openness_s1",label:"教与会意：六彻",sentences:[["「彼教不学，承意不彼。"],["目彻为明，耳彻为聪，鼻彻为颤，口彻为甘，心彻为知，知彻为德。"]]},{id:"ww_openness_s2",label:"道不欲壅：堵塞与众害",sentences:[["凡道不欲壅，壅则哽，哽而不止则跈，跈则众害生。"]]},{id:"ww_openness_s3",label:"恃息与孔窍：天穿而人塞",sentences:[["物之有知者恃息。其不殷，非天之罪。"],["天之穿之，日夜无降，人则顾塞其窦。"]]},{id:"ww_openness_s4",label:"居室与心：空虚、天游与相攘",sentences:[["胞有重阆，心有天游。"],["室无空虚，则妇姑勃谿；心无天游，则六凿相攘。"]]},{id:"ww_openness_s5",label:"大林丘山：末句存疑",sentences:[["大林丘山之善于人也，亦神者不胜。」"]]}],T=[{id:"ww_openness_bijiao",term:"彼教不学，承意不彼",pinyin:"—",meaning:"句法与彼的所指有不同解释。可联系教学、会意与不逐迹等理解，暂不作逐字定译，也不直接否定学习。"},{id:"ww_openness_che",term:"彻、鼻彻为颤、知彻为德",pinyin:"chè、bí chè wéi chàn、zhì chè wéi dé",meaning:"彻联系通达。颤保留来稿字形，有异文与训释问题，不按现代颤抖建立意义；德不只等同现代道德品格。"},{id:"ww_openness_yong",term:"壅、哽、跈",pinyin:"yōng、gěng、—",meaning:"壅、哽涉及堵塞、梗阻；跈有不同音义，暂不强定。递进比喻不直接对应现代医学病理。"},{id:"ww_openness_xi",term:"恃息、不殷、无降、窦",pinyin:"shì xī、bù yīn、wú jiàng、dòu",meaning:"依赖气息、充盛、减衰与孔窍等，具体句法需校读。不将其概括为所有疾病都是个人自堵造成。"},{id:"ww_openness_bao",term:"胞有重阆",pinyin:"bāo yǒu chóng láng",meaning:"胞、重阆的名物与音义有不同解释，可联系体内空间等理解，不作确定解剖学说明。"},{id:"ww_openness_tianyou",term:"天游、妇姑勃谿、六凿相攘",pinyin:"tiān yóu、fù gū bó xī、liù záo xiāng rǎng",meaning:"天游涉及心的自然游动；妇姑为媳妇与婆婆，勃谿为争执；六凿通常联系前文六种功能，相攘为相争相扰等。不把空间解释作家庭冲突的完整原因。"},{id:"ww_openness_shenzhe",term:"大林丘山之善于人也，亦神者不胜",pinyin:"dà lín qiū shān zhī shàn yú rén yě, yì shén zhě bù shèng",meaning:"末句有不同句法与训释。精神不能充分承受山林之益是一种贯通读法，保留存疑，不作为唯一结论。"}],j=[{id:"ww_name_s1",label:"德名、谋知与事务条件",sentences:[["德溢乎名，名溢乎暴，谋稽乎誸，知出乎争，柴生乎守，官事果乎众宜。"]]},{id:"ww_name_s2",label:"春雨与锄治：生长与倒植",sentences:[["春雨日时，草木怒生，铫鎒于是乎始修，"],["草木之倒植者过半而不知其然。"]]},{id:"ww_name_s3",label:"静默与安宁：劳者之务",sentences:[["静默可以补病，眦媙可以休老，宁可以止遽。"],["虽然，若是劳者之务也，非佚者之所未尝过而问焉；"]]},{id:"ww_name_s4",label:"骇天下与骇世：不同关切",sentences:[["圣人之所以骇天下，神人未尝过而问焉；"],["贤人所以骇世，圣人未尝过而问焉；"]]},{id:"ww_name_s5",label:"骇国与合时：不以惊叹为终点",sentences:[["君子所以骇国，贤人未尝过而问焉；"],["小人所以合时，君子未尝过而问焉。"]]}],S=[{id:"ww_name_de",term:"德溢乎名，名溢乎暴",pinyin:"dé yì hū míng, míng yì hū —",meaning:"德、名、溢与暴的关系有不同训释。暴可涉及显露、外著等，不未经说明定为暴力，也不把两句直接改成必然退化链。"},{id:"ww_name_xian",term:"谋稽乎誸，知出乎争",pinyin:"móu jī hū xián, zhì chū hū zhēng",meaning:"稽涉及停留、稽留等；誸涉及迫急；知联系智。可讨论谋虑、智巧与处境的关系，不断言所有知识只出于争夺。"},{id:"ww_name_zhai",term:"柴生乎守，官事果乎众宜",pinyin:"zhài shēng hū shǒu, guān shì guǒ hū zhòng yí",meaning:"柴通常联系闭塞、阻隔，守涉及执守；众宜涉及多方面合宜。不能只译为多数人赞同，也不说所有坚持都必然造成闭塞。"},{id:"ww_name_nusheng",term:"春雨日时、怒生、铫鎒",pinyin:"chūn yǔ rì shí、nù shēng、yáo nòu",meaning:"涉及春雨适时、草木蓬勃生长与锄耨农具。日及农具字形音义须依底本统一，怒不作愤怒理解。"},{id:"ww_name_daozhi",term:"草木之倒植者过半而不知其然",pinyin:"cǎo mù zhī dào zhí zhě guò bàn ér bù zhī qí rán",meaning:"倒植可联系翻倒、锄除等，整句与上下文关系有争议。保留成就与损伤并存的阅读可能，不推成反对所有耕作。"},{id:"ww_name_ziwei",term:"静默、眦媙、宁可以止遽",pinyin:"jìng mò、—、níng kě yǐ zhǐ jù",meaning:"涉及静养、休老与平息急迫等。眦媙音义不强定，不对应具体现代疗法；这些句子不作为治疗效果保证。"},{id:"ww_name_laoyi",term:"劳者、佚者、非佚者之所未尝过而问焉",pinyin:"láo zhě、yì zhě、—",meaning:"劳扰者与安逸者等，佚联系逸。末句否定关系与句法难解，暂联系不同关切理解，不以否定词机械作唯一译文。"},{id:"ww_name_hai",term:"骇、过而问焉、合时",pinyin:"hài、guò ér wèn yān、hé shí",meaning:"骇涉及使人惊异、震动；过问涉及前往关注；合时为合乎时俗等。不将神人、圣人、贤人、君子、小人排成全书统一修养等级。"}],A=[{id:"ww_imitation_s1",label:"演门哀毁：得官与群体效仿",sentences:[["演门有亲死者，以善毁爵为官师，其党人毁而死者半。"]]},{id:"ww_imitation_s2",label:"让天下与拒绝：许由、务光",sentences:[["尧与许由天下，许由逃之；汤与务光，务光怒之；"]]},{id:"ww_imitation_s3",label:"纪他与弟子：窾水与吊唁",sentences:[["纪他闻之，帅弟子而蹲于窾水，诸侯吊之。"]]},{id:"ww_imitation_s4",label:"申徒狄：后续投河",sentences:[["三年，申徒狄因以踣河。"]]}],C=[{id:"ww_imitation_yanmen",term:"演门、有亲死者",pinyin:"yǎn mén、yǒu qīn sǐ zhě",meaning:"演门通常作地名；有亲人去世者。具体地点与人物不在此坐实。"},{id:"ww_imitation_shanhui",term:"以善毁爵为官师",pinyin:"—",meaning:"善毁涉及居丧哀毁、形体损伤；爵为官师通常联系授爵任官等。保留断句疑义，不把毁爵直接解释成毁坏爵杯。"},{id:"ww_imitation_dangren",term:"党人毁而死者半",pinyin:"dǎng rén huǐ ér sǐ zhě bàn",meaning:"党人涉及同乡或同一群体；毁而死写过度损伤身体致死。半按寓言的强烈概括阅读，不作为可核验人口统计。"},{id:"ww_imitation_rang",term:"与许由天下、务光",pinyin:"yǔ xǔ yóu tiān xià、wù guāng",meaning:"与为给予，涉及让天下及拒绝的传说。不据此认定所有让位虚伪，或受让者都在揭穿邀名。"},{id:"ww_imitation_kuanshui",term:"纪他、帅弟子、蹲于窾水",pinyin:"jì tā、shuài dì zǐ、—",meaning:"纪他为篇中人物；帅联系率领；蹲的字义、音读有难点，通常联系投身、沉入水中。窾水为水名，不按现代蹲坐水边释义。"},{id:"ww_imitation_bo",term:"吊之、申徒狄、踣河",pinyin:"diào zhī、shēn tú dí、bó hé",meaning:"吊为吊唁；申徒狄见古代传说；踣为仆倒，此处联系投河。具体动机不由简短叙事全部复原，也不把死亡当作值得效仿的高洁证明。"}],V=[{id:"ww_meaning_s1",label:"荃与鱼：所得与器具",sentences:[["荃者所以在鱼，得鱼而忘荃；"]]},{id:"ww_meaning_s2",label:"蹄与兔：不以工具代替目的",sentences:[["蹄者所以在兔，得兔而忘蹄；"]]},{id:"ww_meaning_s3",label:"言与意：得意忘言",sentences:[["言者所以在意，得意而忘言。"]]},{id:"ww_meaning_s4",label:"篇末：寻找能够交谈的忘言者",sentences:[["吾安得夫忘言之人而与之言哉！"]]}],I=[{id:"ww_meaning_quan",term:"荃、蹄",pinyin:"quán、tí",meaning:"荃通常联系筌、捕鱼器具，保留来稿字形；蹄为捕兔器具等，不是兔子的蹄足。具体器具形制不在此复原。"},{id:"ww_meaning_zai",term:"所以在鱼、所以在兔、所以在意",pinyin:"suǒ yǐ zài yú、suǒ yǐ zài tù、suǒ yǐ zài yì",meaning:"器具与所求、言语与意旨的关系。在的具体训释可依注本比较，不以工具与目的比喻穷尽全部语言功能。"},{id:"ww_meaning_deyi",term:"得意、忘言",pinyin:"dé yì、wàng yán",meaning:"得意为领会意旨，不是得意自满；忘言可理解为不执著言辞，不等于失去语言能力，也不使自称悟意者免于文字与事实检验。"},{id:"ww_meaning_anyan",term:"吾安得夫忘言之人而与之言哉",pinyin:"wú ān dé fú wàng yán zhī rén ér yǔ zhī yán zāi",meaning:"寻找忘言者而仍欲交谈，形成篇末反常意味。不能只解为禁止言说，也不把忘言当作拒绝解释与校正的理由。"}];return(U,n)=>{const v=l("DaoReadingPrelude"),s=l("DaoTextReading"),d=l("DaoKeywordCards"),r=l("DaoLineGuide");return N(),R("div",null,[n[0]||(n[0]=i('<h1 id="庄子·外物" tabindex="-1">庄子·外物 <a class="header-anchor" href="#庄子·外物" aria-label="Permalink to &quot;庄子·外物&quot;">​</a></h1><h2 id="篇名与阅读范围" tabindex="-1">篇名与阅读范围 <a class="header-anchor" href="#篇名与阅读范围" aria-label="Permalink to &quot;篇名与阅读范围&quot;">​</a></h2><blockquote><p><strong>外物</strong></p><p>《庄子》第二十六篇，属于杂篇。篇名取自开头「外物不可必」。</p></blockquote><p>外物不只指身外财货。</p><p>本篇开头将遭遇、信任与亲爱纳入结果无法完全保证的范围，随后又以粮食、水、鱼与珠，展开不同的关系：</p><p><strong>人怎样面对不可保证的结果？</strong></p><p><strong>救助是否适合眼前需要？</strong></p><p><strong>行动方法是否与对象相称？</strong></p><p><strong>言辞与知识究竟服务于什么行为？</strong></p>',9)),a(v,{title:"先读前四段：结果、救助、尺度与诗礼发冢",summary:"开篇从外物不可必转入利害焚和；庄周贷粟以涸辙之鲋反省远诺，任公子的大钓扩大行动尺度，儒者发冢则揭露经典说辞如何被用于掠夺。",points:[{label:"先看",text:"忠与孝不能保证信与爱，是否就意味着忠孝无价值，或受害者应为遭遇负责？"},{label:"再问",text:"斗升之水与东海大钓，分别需要怎样的时机、规模与方法？"},{label:"最后",text:"语言可以令人惊叹，也可以替掠夺辩护；怎样从实际行为判断其作用？"}],hint:"全篇十段均已整理：前四段立起「外物不可必」、及时救助、方法与广大，四段之后转入自矜、能力限度、支持条件与天游，末两段收在伤生之评与得意忘言；文末脉络地图、三问、现代引申、索引与校读说明覆盖全篇。"}),n[1]||(n[1]=t("h2",{id:"一、外物不可必·遭遇与利害焚和",tabindex:"-1"},[e("一、外物不可必·遭遇与利害焚和 "),t("a",{class:"header-anchor",href:"#一、外物不可必·遭遇与利害焚和","aria-label":'Permalink to "一、外物不可必·遭遇与利害焚和"'},"​")],-1)),n[2]||(n[2]=t("h3",{id:"原文",tabindex:"-1"},[e("原文 "),t("a",{class:"header-anchor",href:"#原文","aria-label":'Permalink to "原文"'},"​")],-1)),a(s,{sections:p,glossary:o,"default-mode":"classic","aria-label":"外物·外物不可必 原文"}),n[3]||(n[3]=t("blockquote",null,[t("p",null,"**阅读说明：**不同立场的人物遭遇并列，限制行为与结果之间的保证关系，不取消行为的伦理差别。"),t("p",null,"「两陷」「慰暋沈屯」「月固不胜火」等保留疑义，不强定为完整心理学或医学理论。")],-1)),n[4]||(n[4]=t("h3",{id:"生僻字词",tabindex:"-1"},[e("生僻字词 "),t("a",{class:"header-anchor",href:"#生僻字词","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(d,{items:[{term:"伍员",pinyin:["wǔ","yún"],meaning:"通常所称伍子胥。"},{term:"苌弘",pinyin:["cháng","hóng"],meaning:"古代人物，血化碧属相关传说。"},{term:"曾参",pinyin:["zēng","shēn"],meaning:"古代人物，参读 shēn。"},{term:"然",pinyin:["rán"],meaning:"相摩则然的然联系燃理解。"},{term:"霆",pinyin:["tíng"],meaning:"疾雷、霹雳等。"},{term:"县",pinyin:["xuán"],meaning:"联系悬理解。"},{term:"僓然",pinyin:["tuí","rán"],meaning:"衰败、委顿等，音义待统一底本。"}]}),n[5]||(n[5]=t("h3",{id:"核心句引读",tabindex:"-1"},[e("核心句引读 "),t("a",{class:"header-anchor",href:"#核心句引读","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(r,{title:"结果不能完全保证，不等于行为没有差别",subtitle:"反省利害的耗损，也不替外部侵害免责。",lines:[{text:"外物不可必。",tone:"不可期必",guide:"限制以自身意志保证外在结果。不是说不能影响结果，也不是任何准备与行动都无用。可以努力、判断与保护自己，同时承认未能完全掌控的部分。"},{text:"龙逢诛，比干戮，箕子狂，恶来死，桀、纣亡。",tone:"不同立场",guide:"忠臣、宠臣与君主等遭遇并列，不只说忠臣没有好报。也不能推出忠与佞、谏与暴都同样正当，或任何道路最终结局都一样。"},{text:"忠未必信……孝未必爱。",tone:"关系",guide:"付出与对方回应之间没有自动保证。不能据此要求子女无限尽孝、臣下无限牺牲，也不能说被忽视与侵害只是没有看开。关系中的责任与必要边界仍需判断。"},{text:"藏其血，三年而化为碧。",tone:"传说",guide:"神异意象延续忠而遭难的叙述，可能带有褒扬或悲剧意味，不强定作者只为讽刺或只为歌颂。它不是现实血液化玉的证据。"},{text:"心若县于天地之间。",tone:"悬心",guide:"以悬的意象写难安、无所着落。可以联系忧患的体验，不直接给人物或读者作现代精神疾病诊断。"},{text:"利害相摩，生火甚多，众人焚和。",tone:"摩与火",guide:"将前文摩与火收束到利害牵动、和受到耗损的图景。可反省持续患得患失，但不能说外部暴力与匮乏都不会伤人，伤害全由自己内心造成。"},{text:"月固不胜火，于是乎有僓然而道尽。",tone:"疑难收束",guide:"月的字形与所指仍需校读，不只定为清凉虚静之心。可以保留焚和与衰败的叙述方向，不推成一旦焦虑便无从恢复的定律。"}]}),n[6]||(n[6]=i('<h3 id="忠与孝不能兑换回应" tabindex="-1">忠与孝不能兑换回应 <a class="header-anchor" href="#忠与孝不能兑换回应" aria-label="Permalink to &quot;忠与孝不能兑换回应&quot;">​</a></h3><table tabindex="0"><thead><tr><th>所为</th><th>期待的回应</th><th>本段限制</th></tr></thead><tbody><tr><td>忠</td><td>信任</td><td>忠未必信</td></tr><tr><td>孝</td><td>亲爱</td><td>孝未必爱</td></tr></tbody></table><p>不保证回报，不等于不值得做。</p><p>更不等于：</p><p><strong>只要做得更多，就一定能换来信任与爱。</strong></p><p>可以同时保留：</p><ul><li>对自身行为的判断。</li><li>对对方责任的检查。</li><li>不能完全控制结果的承认。</li><li>必要的保护、退出与支持。</li></ul><h3 id="心的耗损与外部伤害" tabindex="-1">心的耗损与外部伤害 <a class="header-anchor" href="#心的耗损与外部伤害" aria-label="Permalink to &quot;心的耗损与外部伤害&quot;">​</a></h3><p>本段从人物遭害写到利害焚和。</p><p>两层不能混同：</p><p><strong>外部行为可能造成真实伤害。</strong></p><p><strong>持续的利害牵动也可能加重耗损。</strong></p><p>反省自身处身，不免除加害者责任。</p><p>身处忧患者也不应因未能虚静，再被指责为自行焚和。</p><h2 id="二、庄周贷粟·涸辙之鲋与救助时机" tabindex="-1">二、庄周贷粟·涸辙之鲋与救助时机 <a class="header-anchor" href="#二、庄周贷粟·涸辙之鲋与救助时机" aria-label="Permalink to &quot;二、庄周贷粟·涸辙之鲋与救助时机&quot;">​</a></h2><h3 id="原文-1" tabindex="-1">原文 <a class="header-anchor" href="#原文-1" aria-label="Permalink to &quot;原文&quot;">​</a></h3>',16)),a(s,{sections:h,glossary:g,"default-mode":"classic","aria-label":"外物·庄周贷粟与涸辙之鲋 原文"}),n[7]||(n[7]=t("blockquote",null,[t("p",null,"**阅读说明：**故事以两组相似答复构成讽刺。监河侯的承诺不能解决当前请求，但原文未直接叙述他后来是否兑现，也未明说他蓄意欺骗。"),t("p",null,"鲋鱼按寓言理解，不用东海、水族与斗升之水建立现实救鱼方案。")],-1)),n[8]||(n[8]=t("h3",{id:"生僻字词-1",tabindex:"-1"},[e("生僻字词 "),t("a",{class:"header-anchor",href:"#生僻字词-1","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(d,{items:[{term:"贷粟",pinyin:["dài","sù"],meaning:"借粮。"},{term:"邑金",pinyin:["yì","jīn"],meaning:"通常联系封邑收入理解。"},{term:"鲋",pinyin:["fù"],meaning:"通常联系鲫鱼理解。"},{term:"波臣",pinyin:["bō","chén"],meaning:"寓言中的水族身份。"},{term:"激",pinyin:["jī"],meaning:"引导水流等。"},{term:"肆",pinyin:["sì"],meaning:"店铺。"}]}),n[9]||(n[9]=t("h3",{id:"核心句引读-1",tabindex:"-1"},[e("核心句引读 "),t("a",{class:"header-anchor",href:"#核心句引读-1","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(r,{title:"救助的价值，不只看数额，也看是否来得及",subtitle:"眼前所需不能由未来的大承诺替代。",lines:[{text:"庄周家贫，故往贷粟于监河侯。",tone:"实际需要",guide:"庄周主动借粮，说明承认外物不可必不等于拒绝一切求助。贫困涉及现实资源，不能只用心境解释。"},{text:"我将得邑金，将贷子三百金，可乎？",tone:"未来答复",guide:"答应的数额大，时间却放在取得邑金之后。可以指出当前需求未获满足，不直接断言对方必不会得到收入或绝不兑现。"},{text:"君岂有斗升之水而活我哉！",tone:"少而及时",guide:"鱼求的是当前能维持生存的水，大小并非唯一评价。少量但及时适宜的帮助，可能比远期大量承诺更重要。"},{text:"激西江之水而迎子，可乎？",tone:"镜像",guide:"故事中的庄周复制诺、未来安排、大量援助与可乎的形式，使监河侯的答复变得陌生。不是可执行的调水计划。"},{text:"吾失我常与，我无所处。",tone:"条件",guide:"鱼失去平常相与的生存条件，强调需要与所处环境的关系。不应只说鱼从来不需更多水，或原有资源已足以应付一切情境。"},{text:"曾不如早索我于枯鱼之肆。",tone:"迟到",guide:"以可能成为干鱼的结局反讽救助迟到。不是正文已经报告鱼死，也不是称赞去买干鱼可以替代救命。"}]}),n[10]||(n[10]=i('<h3 id="两组答复的镜像" tabindex="-1">两组答复的镜像 <a class="header-anchor" href="#两组答复的镜像" aria-label="Permalink to &quot;两组答复的镜像&quot;">​</a></h3><table tabindex="0"><thead><tr><th>监河侯对庄周</th><th>故事中的庄周对鲋鱼</th></tr></thead><tbody><tr><td>诺</td><td>诺</td></tr><tr><td>我将得邑金</td><td>我且南游吴越之王</td></tr><tr><td>将贷子三百金</td><td>激西江之水而迎子</td></tr><tr><td>可乎</td><td>可乎</td></tr></tbody></table><p>同一句客气答复，放入紧迫情境，暴露出时机错位。</p><p><strong>承诺看似慷慨，不等于眼前已经得到帮助。</strong></p><h3 id="与第一段连读" tabindex="-1">与第一段连读 <a class="header-anchor" href="#与第一段连读" aria-label="Permalink to &quot;与第一段连读&quot;">​</a></h3><p>第一段限制外在回应的保证。</p><p>本段却让庄周实际求助，并对不适宜的答复作出批评。</p><p>两者共同提醒：</p><p><strong>不能完全保证他人回应，也仍可以提出需要、判断答复并寻求帮助。</strong></p><p>不必归结为：</p><p><strong>既然外物不可必，便不应依赖任何人。</strong></p><h2 id="三、任公子大钓·对象、方法与广大通达" tabindex="-1">三、任公子大钓·对象、方法与广大通达 <a class="header-anchor" href="#三、任公子大钓·对象、方法与广大通达" aria-label="Permalink to &quot;三、任公子大钓·对象、方法与广大通达&quot;">​</a></h2><h3 id="原文-2" tabindex="-1">原文 <a class="header-anchor" href="#原文-2" aria-label="Permalink to &quot;原文&quot;">​</a></h3>',13)),a(s,{sections:u,glossary:m,"default-mode":"classic","aria-label":"外物·任公子大钓 原文"}),n[11]||(n[11]=t("blockquote",null,[t("p",null,"**文字说明：**制河、揭竿累等沿用来稿，不默默改字。"),t("p",null,"大钓、大鱼与供食范围按夸张寓言阅读，不作为捕鱼技术或坚持必成功的公式。「县令」不直接按现代县官释义。")],-1)),n[12]||(n[12]=t("h3",{id:"生僻字词-2",tabindex:"-1"},[e("生僻字词 "),t("a",{class:"header-anchor",href:"#生僻字词-2","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(d,{items:[{term:"缁",pinyin:["zī"],meaning:"黑色，此处联系粗大黑色钓绳。"},{term:"犗",pinyin:["jiè"],meaning:"通常指阉割过的牛等。"},{term:"会稽",pinyin:["kuài","jī"],meaning:"古地名。"},{term:"期年",pinyin:["jī","nián"],meaning:"满一年。"},{term:"鬐",pinyin:["qí"],meaning:"鱼背鳍等。"},{term:"侔",pinyin:["móu"],meaning:"相比、相等。"},{term:"腊",pinyin:["xī"],meaning:"此处涉及制成干鱼。"},{term:"辁才",pinyin:["quán","cái"],meaning:"小才、浅识。"}]}),n[13]||(n[13]=t("h3",{id:"核心句引读-2",tabindex:"-1"},[e("核心句引读 "),t("a",{class:"header-anchor",href:"#核心句引读-2","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(r,{title:"不只问大小，也问方法是否与对象相称",subtitle:"大钓与小水各有语境，不让固定尺度替代判断。",lines:[{text:"大钩巨缁，五十犗以为饵。",tone:"扩大尺度",guide:"以巨大准备将读者带离日常钓鱼范围，不能视作实际技术，也不证明资源投入越大就越正确。需要与所面对的对象相接阅读。"},{text:"旦旦而钓，期年不得鱼。",tone:"等待",guide:"持续行动却没有即时收获，限制以立刻见效作为唯一评价。后来得鱼是情节，不是保证所有坚持最终成功；继续投入也仍可检查条件与代价。"},{text:"白波若山，海水震荡。",tone:"对象",guide:"大鱼声势与大钓准备相互对应，表现超出小水域经验的对象。不能据此否定小范围研究与细部工作，只需辨明其能处理什么问题。"},{text:"离而腊之……莫不厌若鱼者。",tone:"广泛作用",guide:"所得被写为可及众人的饱食，超出个人小得。供食范围仍是夸张，不给任公子与大鱼建立唯一政治象征，也不把广泛效用自动等同所有过程都正当。"},{text:"辁才讽说之徒，皆惊而相告也。",tone:"传述",guide:"惊叹转述不保证领会风范。不能因此说讲故事、传播知识都无价值；问题在是否只停留于奇观与名声。"},{text:"守鲵鲋，其于得大鱼难矣！",tone:"方法范围",guide:"小水域、小方式难以取得本段的大鱼，限制方法适用范围。不等于小鱼无价值，也不要求所有生活都扩大到东海大钓。"},{text:"饰小说以干县令，其于大达亦远矣。",tone:"言与达",guide:"小说为琐细言说，县令有高名美誉等解释。批评经营说辞与真正通达之间的距离，不简单译为写小说讨好县官，也不说精细说明一概无用。"}]}),n[14]||(n[14]=i('<h3 id="涸辙之鲋与任公子" tabindex="-1">涸辙之鲋与任公子 <a class="header-anchor" href="#涸辙之鲋与任公子" aria-label="Permalink to &quot;涸辙之鲋与任公子&quot;">​</a></h3><table tabindex="0"><thead><tr><th>涸辙之鲋</th><th>任公子大钓</th></tr></thead><tbody><tr><td>当前生存急需</td><td>面对广大对象</td></tr><tr><td>斗升之水</td><td>大钩巨缁、巨大鱼饵</td></tr><tr><td>大而迟到的承诺不适宜</td><td>小而局促的方法不足</td></tr><tr><td>检查救助时机</td><td>检查方法范围</td></tr></tbody></table><p>两段不互相否定。</p><p><strong>对需要及时小水的鱼，不能只许诺大江。</strong></p><p><strong>对寓言中的东海大鱼，也不能把小沟方法当作充分准备。</strong></p><p>合宜是两段的比较线索，不必据此宣称两段构成作者预设的严格论证。</p><h3 id="任氏风范不只是听闻奇事" tabindex="-1">任氏风范不只是听闻奇事 <a class="header-anchor" href="#任氏风范不只是听闻奇事" aria-label="Permalink to &quot;任氏风范不只是听闻奇事&quot;">​</a></h3><p>能说出故事，不等于已经具备相应识见。</p><p>同样：</p><p><strong>不善言说，也不自动证明已经广大通达。</strong></p><p>行动、准备、判断与效果，不能只由说辞好坏替代。</p><h2 id="四、儒者发冢·经典说辞与掠夺" tabindex="-1">四、儒者发冢·经典说辞与掠夺 <a class="header-anchor" href="#四、儒者发冢·经典说辞与掠夺" aria-label="Permalink to &quot;四、儒者发冢·经典说辞与掠夺&quot;">​</a></h2><h3 id="原文-3" tabindex="-1">原文 <a class="header-anchor" href="#原文-3" aria-label="Permalink to &quot;原文&quot;">​</a></h3>',13)),a(s,{sections:b,glossary:c,"default-mode":"classic","aria-label":"外物·儒者发冢 原文"}),n[15]||(n[15]=t("blockquote",null,[t("p",null,"**断句说明：**对话归属与引号划分有差异，此处沿用来稿，以指挥、报告、引诗取珠的叙事关系阅读。"),t("p",null,"所引「青青之麦……」不见于今本《诗经》，不指认今本某篇。大儒、小儒是讽刺叙事中的人物，不等同所有儒者。")],-1)),n[16]||(n[16]=t("h3",{id:"生僻字词-3",tabindex:"-1"},[e("生僻字词 "),t("a",{class:"header-anchor",href:"#生僻字词-3","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(d,{items:[{term:"发冢",pinyin:["fā","zhǒng"],meaning:"掘墓。"},{term:"胪传",pinyin:["lú","chuán"],meaning:"传语、传声。"},{term:"裙襦",pinyin:["qún","rú"],meaning:"下裙与短衣。"},{term:"陵陂",pinyin:["líng","bēi"],meaning:"丘陵坡地等。"},{term:"顪",pinyin:["huì"],meaning:"颊、颌附近须毛等，细义待辨。"},{term:"颐",pinyin:["yí"],meaning:"下颌等。"},{term:"徐",pinyin:["xú"],meaning:"缓慢。"}]}),n[17]||(n[17]=t("h3",{id:"核心句引读-3",tabindex:"-1"},[e("核心句引读 "),t("a",{class:"header-anchor",href:"#核心句引读-3","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(r,{title:"引用什么，不等于实际保护什么",subtitle:"道德语言与细心，都不能单独证明行为正当。",lines:[{text:"儒以《诗》、《礼》发冢。",tone:"反差",guide:"经典与掘墓并置，讽刺高尚语言可能进入掠夺过程。不是只说不懂经典者行恶，也不能反推所有经典皆有害。"},{text:"东方作矣，事之何若？",tone:"进度",guide:"天将明与进度询问带来时间压力。称号体面却服务于掘墓分工，揭露身份与行为脱节，不是客观描述所有儒者日常。"},{text:"生不布施，死何含珠为？",tone:"辩护",guide:"在取珠场景中，道德批评被用于转移追问：从我为何掘墓，转向死者为何含珠。原文未证明死者实际吝啬，也未说珠将用于救助。"},{text:"徐别其颊，无伤口中珠。",tone:"保护对象",guide:"谨慎的对象被点明为珠，形成价值倒置。此处重在辨析所保护者，不需要把身体操作转成详细技术说明。"},{text:"无伤口中珠。",tone:"言行检验",guide:"无伤的措辞不自动意味着关怀人。判断语言的作用，还要看实际行为、受损者与受保护的利益。"}]}),n[18]||(n[18]=i(`<h3 id="道德说辞怎样转移责任" tabindex="-1">道德说辞怎样转移责任 <a class="header-anchor" href="#道德说辞怎样转移责任" aria-label="Permalink to &quot;道德说辞怎样转移责任&quot;">​</a></h3><p>故事中的引诗把注意力引向死者：</p><p><strong>活着为何不布施？死后为何含珠？</strong></p><p>但现场仍需要追问：</p><p><strong>这些话为什么被说出？正在配合什么行为？</strong></p><p>对他人的批评，不能自动使自己的取财正当。</p><h3 id="与第三段的区别" tabindex="-1">与第三段的区别 <a class="header-anchor" href="#与第三段的区别" aria-label="Permalink to &quot;与第三段的区别&quot;">​</a></h3><table tabindex="0"><thead><tr><th>第三段</th><th>第四段</th></tr></thead><tbody><tr><td>饰小说以求高名</td><td>引诗礼而掘墓</td></tr><tr><td>言说经营不等于广大通达</td><td>道德说辞不等于行为正当</td></tr><tr><td>检查识见与方法</td><td>检查利益、损害与价值次序</td></tr></tbody></table><p><strong>会说，不等于通达。</strong></p><p><strong>会说正当的话，也不等于正在做正当的事。</strong></p><p>两段共同限制言说的充分性，不是取消交流与经典学习。</p><h2 id="一至四段·阶段性脉络" tabindex="-1">一至四段·阶段性脉络 <a class="header-anchor" href="#一至四段·阶段性脉络" aria-label="Permalink to &quot;一至四段·阶段性脉络&quot;">​</a></h2><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>第1段·外物不可必</span></span>
<span class="line"><span>    不同人物的遭遇</span></span>
<span class="line"><span>    → 忠未必信、孝未必爱</span></span>
<span class="line"><span>    → 行为与回应无自动保证</span></span>
<span class="line"><span>    → 摩与火的自然意象</span></span>
<span class="line"><span>    → 利害牵动、焚和与衰败</span></span>
<span class="line"><span></span></span>
<span class="line"><span>第2段·庄周贷粟</span></span>
<span class="line"><span>    借粮的现实需要</span></span>
<span class="line"><span>    → 未来三百金</span></span>
<span class="line"><span>    → 故事中的鲋鱼求水</span></span>
<span class="line"><span>    → 大而远的镜像答复</span></span>
<span class="line"><span>    → 揭露救助时机错位</span></span>
<span class="line"><span></span></span>
<span class="line"><span>第3段·任公子大钓</span></span>
<span class="line"><span>    巨大准备</span></span>
<span class="line"><span>    → 持续等待</span></span>
<span class="line"><span>    → 大鱼与大钓相应</span></span>
<span class="line"><span>    → 广泛供食</span></span>
<span class="line"><span>    → 传述不等于领会</span></span>
<span class="line"><span>    → 方法与对象、说辞与通达</span></span>
<span class="line"><span></span></span>
<span class="line"><span>第4段·儒者发冢</span></span>
<span class="line"><span>    经典与掘墓并置</span></span>
<span class="line"><span>    → 指挥与报告</span></span>
<span class="line"><span>    → 引诗转移责任</span></span>
<span class="line"><span>    → 谨慎保护珠</span></span>
<span class="line"><span>    → 身份、说辞与实际行为的反差</span></span></code></pre></div><h3 id="阶段性三问" tabindex="-1">阶段性三问 <a class="header-anchor" href="#阶段性三问" aria-label="Permalink to &quot;阶段性三问&quot;">​</a></h3><h4 id="第一问-我能影响什么-又不能保证什么" tabindex="-1">第一问：我能影响什么，又不能保证什么？ <a class="header-anchor" href="#第一问-我能影响什么-又不能保证什么" aria-label="Permalink to &quot;第一问：我能影响什么，又不能保证什么？&quot;">​</a></h4><p>不把结果完全受控当成行动前提，也不把不可必当成放弃保护与求助的理由。</p><h4 id="第二问-帮助与方法-是否适合当前对象" tabindex="-1">第二问：帮助与方法，是否适合当前对象？ <a class="header-anchor" href="#第二问-帮助与方法-是否适合当前对象" aria-label="Permalink to &quot;第二问：帮助与方法，是否适合当前对象？&quot;">​</a></h4><p>时机、规模与适用范围，需要一起判断。</p><p>大不是自动正确，小也不是天然无用。</p><h4 id="第三问-语言与能力-实际服务于谁" tabindex="-1">第三问：语言与能力，实际服务于谁？ <a class="header-anchor" href="#第三问-语言与能力-实际服务于谁" aria-label="Permalink to &quot;第三问：语言与能力，实际服务于谁？&quot;">​</a></h4><p>不只听称号、引文与批评，还看行动保护了什么、损害了什么。</p><h3 id="阶段性收束" tabindex="-1">阶段性收束 <a class="header-anchor" href="#阶段性收束" aria-label="Permalink to &quot;阶段性收束&quot;">​</a></h3><blockquote><p><strong>结果不能全由自身保证；行动仍需合宜，言辞仍须接受实际行为的检验。</strong></p></blockquote><p>这是前四段的串读线索，不是全篇唯一主旨。</p><h2 id="五、老莱子与仲尼·自矜、名号与行动后果" tabindex="-1">五、老莱子与仲尼·自矜、名号与行动后果 <a class="header-anchor" href="#五、老莱子与仲尼·自矜、名号与行动后果" aria-label="Permalink to &quot;五、老莱子与仲尼·自矜、名号与行动后果&quot;">​</a></h2><h3 id="关键节引" tabindex="-1">关键节引 <a class="header-anchor" href="#关键节引" aria-label="Permalink to &quot;关键节引&quot;">​</a></h3>`,26)),a(s,{sections:w,glossary:_,"default-mode":"classic","aria-label":"外物·老莱子与仲尼 关键节引"}),n[19]||(n[19]=t("blockquote",null,[t("p",null,"**重要说明：**来稿未提供完整连续原文。以上只收录能够明确辨认的关键引句，不代表本段全文。"),t("p",null,"弟子出薪、描述外貌、老莱子辨认仲尼、仲尼求教，以及惠以欢为等上下文，待连续正文补齐后再纳入原文组件。")],-1)),n[20]||(n[20]=t("h3",{id:"生僻字词-4",tabindex:"-1"},[e("生僻字词 "),t("a",{class:"header-anchor",href:"#生僻字词-4","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(d,{items:[{term:"躬矜",pinyin:["gōng","jīn"],meaning:"自身的矜持、自夸等。"},{term:"容知",pinyin:["róng","zhì"],meaning:"外在显露的智巧等。"},{term:"骜",pinyin:["ào"],meaning:"轻忽、傲视等，依语境辨析。"},{term:"窭",pinyin:["jù"],meaning:"贫乏。"},{term:"两忘",pinyin:["liǎng","wàng"],meaning:"联系誉尧非桀两端理解。"},{term:"踌躇",pinyin:["chóu","chú"],meaning:"可联系从容、审慎等，不只指犹豫。"}]}),n[21]||(n[21]=t("h3",{id:"核心句引读-4",tabindex:"-1"},[e("核心句引读 "),t("a",{class:"header-anchor",href:"#核心句引读-4","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(r,{title:"关心天下，也需要检查自身的姿态与做法",subtitle:"反省善意，不等于停止关怀；放下自矜，不等于毁弃知识。",lines:[{text:"视若营四海。",tone:"人物姿态",guide:"弟子从神情感到经营天下的负荷，构成寓言中的人物辨识。不是历史外貌记录，也不能判断所有承担公共事务者都在自我夸示。"},{text:"去汝躬矜与汝容知。",tone:"去矜",guide:"把提醒落在自矜与智巧显露，不能扩成不要有知识、没有自尊才正确。可以反省是否把德与知当成安排他人的资格。"},{text:"不忍一世之伤，而骜万世之患。",tone:"后果",guide:"以眼前与长远形成强烈责问，提醒施为需要考虑后果。不是证明每次救助都造成长远伤害，也不能用可能的未来问题拒绝眼前必要帮助。"},{text:"相引以名，相结以隐。",tone:"牵引",guide:"关注名与结合的关系，隐的细义仍需辨析。不能断言所有共同原则都是伪装、所有交往都有秘密恶意。"},{text:"与其誉尧而非桀，不如两忘而闭其所誉。",tone:"名号",guide:"可以限制以誉非名号证明自己的方式，不直接取消具体善恶判断。暴政、伤害与保护仍需按事实辨明。"},{text:"圣人踌躇以兴事，以每成功。",tone:"仍可兴事",guide:"紧接警惕行动的话，仍说兴事，不能只留下不作为。每的训释不确定，不译成每次必定成功；从容也不等于拖延紧急救助。"},{text:"其载焉终矜尔！",tone:"回到自矜",guide:"末句有难点，但再次出现矜，可与去躬矜对读。不凭此补造一个确定的心理诊断或修养流程。"}]}),n[22]||(n[22]=i('<h3 id="与涸辙之鲋连读" tabindex="-1">与涸辙之鲋连读 <a class="header-anchor" href="#与涸辙之鲋连读" aria-label="Permalink to &quot;与涸辙之鲋连读&quot;">​</a></h3><p>涸辙之鲋强调：</p><p><strong>不能用遥远的大承诺，推迟当下必要的帮助。</strong></p><p>本段提醒：</p><p><strong>回应眼前痛苦，也需要检查做法与后果。</strong></p><p>两者不是择一：</p><table tabindex="0"><thead><tr><th>不能忽略</th><th>也不能忽略</th></tr></thead><tbody><tr><td>当下急难</td><td>行动可能产生的后果</td></tr><tr><td>及时帮助</td><td>方法是否适宜</td></tr><tr><td>当事人的具体需要</td><td>自己是否借帮助证明价值</td></tr></tbody></table><p><strong>审慎不是拖延，善意也不是免责。</strong></p><h3 id="仲尼不只是被批评者" tabindex="-1">仲尼不只是被批评者 <a class="header-anchor" href="#仲尼不只是被批评者" aria-label="Permalink to &quot;仲尼不只是被批评者&quot;">​</a></h3><p>来稿描述仲尼改容、继续求教。</p><p>在这一叙事中，他也表现为能够接受提醒的人，而不只是固定的讽刺对象。</p><p>完整原文补齐后，应将这一动作纳入连续阅读，不让批评者的声音完全遮住受教者的回应。</p><h2 id="六、宋元君神龟·能力与处境的限度" tabindex="-1">六、宋元君神龟·能力与处境的限度 <a class="header-anchor" href="#六、宋元君神龟·能力与处境的限度" aria-label="Permalink to &quot;六、宋元君神龟·能力与处境的限度&quot;">​</a></h2><h3 id="原文-4" tabindex="-1">原文 <a class="header-anchor" href="#原文-4" aria-label="Permalink to &quot;原文&quot;">​</a></h3>',14)),a(s,{sections:y,glossary:x,"default-mode":"classic","aria-label":"外物·宋元君神龟 原文"}),n[23]||(n[23]=t("blockquote",null,[t("p",null,"**文字说明：**无遗囗保留来稿呈现问题，囗不作为正常词语解释。无遗生筴也需核对底本。"),t("p",null,"托梦与占验属于寓言中的神异设定，不是现实超自然能力或占卜准确性的证明。")],-1)),n[24]||(n[24]=t("h3",{id:"生僻字词-5",tabindex:"-1"},[e("生僻字词 "),t("a",{class:"header-anchor",href:"#生僻字词-5","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(d,{items:[{term:"被发",pinyin:["pī","fà"],meaning:"披散头发。"},{term:"余且",pinyin:["yú","jū"],meaning:"渔者姓名，且读 jū。"},{term:"占",pinyin:["zhān"],meaning:"占解、占卜。"},{term:"刳",pinyin:["kū"],meaning:"剖。"},{term:"筴",pinyin:["cè"],meaning:"联系策、占验等。"},{term:"见梦",pinyin:["xiàn","mèng"],meaning:"显现于梦中。"},{term:"鹈鹕",pinyin:["tí","hú"],meaning:"捕鱼水鸟。"},{term:"硕师",pinyin:["shuò","shī"],meaning:"大教师、博学之师等。"}]}),n[25]||(n[25]=t("h3",{id:"核心句引读-5",tabindex:"-1"},[e("核心句引读 "),t("a",{class:"header-anchor",href:"#核心句引读-5","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(r,{title:"某种能力出众，不等于能够控制所有处境",subtitle:"能力的边界不能变成对遭害者的责难。",lines:[{text:"渔者余且得予。",tone:"已被捕获",guide:"托梦者先陈述被捕处境，神异与受困同时成立。不能仅因有异能，就要求它必须避开现实中的任何危险。"},{text:"君再欲杀之，再欲活之。",tone:"他人决定",guide:"生死被放入国君的犹疑与决定，显示龟不能控制对方回应。再的具体次数不强定，原文也未给龟直接申辩的机会。"},{text:"杀龟以卜吉。",tone:"谁之吉",guide:"同一决定可能对使用者有利、对被使用者致命。故事中的吉不能直接等同普遍正当；需要看谁获益、谁承受损害。"},{text:"能见梦……不能避余且之网。",tone:"能与不能",guide:"认可故事设定中的异能，才突出其有限。不是证明能力虚假，也不是说明受害者必须靠更高能力保证安全。"},{text:"知有所困，神有所不及。",tone:"限度",guide:"最明确地限制智慧与神异的覆盖范围。能够理解、预测或帮助别人，不等于对自身命运具有完全支配。"},{text:"虽有至知，万人谋之。",tone:"外部力量",guide:"将处境扩大到众人谋取，不把风险只落在个人聪明程度上。可以采取保护措施，却不能许诺足够聪明便绝不遭害。"},{text:"去小知而大知明，去善而自善矣。",tone:"放下经营",guide:"可联系局部拘限、刻意标榜与取悦的反省，不等于停止学习或抛弃关怀。大知也不应重新变成万能护身符。"},{text:"无硕师而能言，与能言者处也。",tone:"成长条件",guide:"不靠大师郑重施教，仍依赖能言者的交往环境。自然形成不是无条件发生，也不证明所有正式教育都多余。"}]}),n[26]||(n[26]=i('<h3 id="能力、价值与安全不能混同" tabindex="-1">能力、价值与安全不能混同 <a class="header-anchor" href="#能力、价值与安全不能混同" aria-label="Permalink to &quot;能力、价值与安全不能混同&quot;">​</a></h3><table tabindex="0"><thead><tr><th>神龟的能力</th><th>未能保证</th></tr></thead><tbody><tr><td>显现于国君之梦</td><td>避开渔网</td></tr><tr><td>提供准确占验的叙事设定</td><td>保全自身生命</td></tr><tr><td>被认作神龟</td><td>获得符合自身需要的回应</td></tr></tbody></table><p>本段与篇首外物不可必相接：</p><p><strong>能够做什么，不等于别人必定怎样对待自己。</strong></p><p>不能因此恢复另一项承诺：</p><p><strong>只要获得真正大知，就保证不会受害。</strong></p><h3 id="婴儿能言不是取消条件" tabindex="-1">婴儿能言不是取消条件 <a class="header-anchor" href="#婴儿能言不是取消条件" aria-label="Permalink to &quot;婴儿能言不是取消条件&quot;">​</a></h3><p>原文自己给出：</p><blockquote><p><strong>与能言者处也。</strong></p></blockquote><p>可以据此区分：</p><ul><li>不由一位大师逐项经营。</li><li>仍依靠环境、接触与成长。</li><li>不强调教者功劳。</li><li>不等于没有学习过程。</li></ul><p><strong>减少不必要的操控，不是撤去必要的支持。</strong></p><h2 id="七、无用之用·直接占用与支持条件" tabindex="-1">七、无用之用·直接占用与支持条件 <a class="header-anchor" href="#七、无用之用·直接占用与支持条件" aria-label="Permalink to &quot;七、无用之用·直接占用与支持条件&quot;">​</a></h2><h3 id="原文-5" tabindex="-1">原文 <a class="header-anchor" href="#原文-5" aria-label="Permalink to &quot;原文&quot;">​</a></h3>',14)),a(s,{sections:q,glossary:f,"default-mode":"classic","aria-label":"外物·无用之用 原文"}),n[27]||(n[27]=t("blockquote",null,[t("p",null,"**阅读说明：**留下足下、挖空周围，是对话中的设想，不是工程方案。"),t("p",null,"本段限制过窄的用途判断，不保证所有被称无用者都有巨大、隐秘的价值。")],-1)),n[28]||(n[28]=t("h3",{id:"生僻字词-6",tabindex:"-1"},[e("生僻字词 "),t("a",{class:"header-anchor",href:"#生僻字词-6","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(d,{items:[{term:"容足",pinyin:["róng","zú"],meaning:"容纳双脚。"},{term:"厕足",pinyin:["cè","zú"],meaning:"置足、立足等。"},{term:"垫",pinyin:["diàn"],meaning:"陷、下陷等。"},{term:"黄泉",pinyin:["huáng","quán"],meaning:"地下深处的泉水等，不专指死后世界。"}]}),n[29]||(n[29]=t("h3",{id:"核心句引读-6",tabindex:"-1"},[e("核心句引读 "),t("a",{class:"header-anchor",href:"#核心句引读-6","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(r,{title:"直接使用的部分，不等于依赖的全部",subtitle:"先检查被排除的条件，再判断其是否多余。",lines:[{text:"子言无用。",tone:"效用判断",guide:"惠子提出无用，未明示唯一标准。不能替他确定只重治国、赚钱或技术操作，先保留对言论效用的提问。"},{text:"知无用而始可与言用矣。",tone:"转问",guide:"庄子先检视被排除为无用的部分，而不是立即列出自己的功效。无用是否可删，需要看它与用的关系。"},{text:"人之所用容足耳。",tone:"直接占用",guide:"两足之下是直接占用，却不是支撑站立、移动与生活的全部条件。例子使局部用途与整体依赖分开。"},{text:"厕足而垫之致黄泉，人尚有用乎？",tone:"删除设想",guide:"通常理解为留下足下而去掉周围，借此检验无用能否排除。具体字句仍需校读，不要求读者照此操作。"},{text:"无用之为用也亦明矣。",tone:"支持条件",guide:"揭示先前未计入的支持关系，不是毫无作用者突然产生神奇效用。也不能据此要求所有事物都以隐藏用途证明存在资格。"}]}),n[30]||(n[30]=i('<h3 id="无用之用不只是「以后会派上用场」" tabindex="-1">无用之用不只是「以后会派上用场」 <a class="header-anchor" href="#无用之用不只是「以后会派上用场」" aria-label="Permalink to &quot;无用之用不只是「以后会派上用场」&quot;">​</a></h3><p>本段不是单纯预言：</p><p><strong>今天无用，明天一定有用。</strong></p><p>它提醒：</p><p><strong>今天的直接使用，可能已经依靠了未被计算的部分。</strong></p><table tabindex="0"><thead><tr><th>过窄判断</th><th>扩大后的检查</th></tr></thead><tbody><tr><td>没有直接踩踏</td><td>是否仍支撑立足？</td></tr><tr><td>没有立即产出</td><td>是否构成活动条件？</td></tr><tr><td>没有被占用</td><td>是否提供周转余地？</td></tr></tbody></table><p>这些后两项是现代引申，不是原文逐项列举。</p><p><strong>不能仅凭直接用途，就决定其余一切都应删除。</strong></p><h2 id="八、游世与天游" tabindex="-1">八、游世与天游 <a class="header-anchor" href="#八、游世与天游" aria-label="Permalink to &quot;八、游世与天游&quot;">​</a></h2><blockquote><p>第八段为长篇论说，分三节整理；分节末尾引号为方便组件独立阅读而作的编辑处理，不表示原文在此结束整段发言。</p></blockquote><h3 id="游于世而不僻-顺人而不失己" tabindex="-1">游于世而不僻，顺人而不失己 <a class="header-anchor" href="#游于世而不僻-顺人而不失己" aria-label="Permalink to &quot;游于世而不僻，顺人而不失己&quot;">​</a></h3><h4 id="原文-6" tabindex="-1">原文 <a class="header-anchor" href="#原文-6" aria-label="Permalink to &quot;原文&quot;">​</a></h4>',12)),a(s,{sections:k,glossary:P,"default-mode":"classic","aria-label":"外物·游世与不失己 原文"}),n[31]||(n[31]=t("blockquote",null,[t("p",null,"**阅读说明：**流遁、决绝及其非至知厚德之任与的语气有解释差异。不将本节定为全面否定隐逸，也不说任何环境都同样自由。")],-1)),n[32]||(n[32]=t("h4",{id:"生僻字词-7",tabindex:"-1"},[e("生僻字词 "),t("a",{class:"header-anchor",href:"#生僻字词-7","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(d,{items:[{term:"流遁",pinyin:["liú","dùn"],meaning:"流遁、退避等，结合语境辨析。"},{term:"决绝",pinyin:["jué","jué"],meaning:"决然断绝等。"},{term:"易世",pinyin:["yì","shì"],meaning:"时世变化。"},{term:"不留行",pinyin:["bù","liú","xíng"],meaning:"不滞留固定行迹等。"},{term:"波",pinyin:["bō"],meaning:"波荡、受扰动。"},{term:"不僻",pinyin:["bù","pì"],meaning:"不偏，不只指位置偏僻。"}]}),n[33]||(n[33]=t("h4",{id:"核心句引读-7",tabindex:"-1"},[e("核心句引读 "),t("a",{class:"header-anchor",href:"#核心句引读-7","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(r,{title:"不让身份、时代与旧有行迹固定处世方式",subtitle:"能够适应，也保留自身；可以改变，也不必全盘迎合。",lines:[{text:"人有能游，且得不游乎！",tone:"游",guide:"游不只是外出，能力与外在行迹不完全重合。不能扩成环境约束无关紧要，前文神龟已呈现真实外部危险。"},{text:"流遁之志，决绝之行。",tone:"姿态",guide:"这组句子的评判方向有不同解释。至少不应只凭退隐或断绝姿态判定境界，也不因此否定合宜的退出与保全。"},{text:"虽相与为君臣，时也。",tone:"时势",guide:"将君臣位置与特定时势相接，限制永恒高下。不是现实权力差异不存在，也不能只用时势取消当事人的责任。"},{text:"至人不留行焉。",tone:"不固定",guide:"可联系不固守旧有行迹理解。过去合宜不保证现在仍宜，改变行为也不自动等于背叛自身。"},{text:"尊古而卑今，学者之流也。",tone:"古今",guide:"批评以古贬今的方式，不是拒绝古代学习。古代经验可以参考，却不直接替代对当下条件的辨明。"},{text:"游于世而不僻，顺人而不失己。",tone:"双重要求",guide:"与世界相接、与人相顺，同时不偏、不失己。顺不是接受一切要求，不失己也不是把每项意见固定不变。"}]}),n[34]||(n[34]=i('<h4 id="身份不是永久价值等级" tabindex="-1">身份不是永久价值等级 <a class="header-anchor" href="#身份不是永久价值等级" aria-label="Permalink to &quot;身份不是永久价值等级&quot;">​</a></h4><p>曾经居高位，不必永远居高位。</p><p>曾经退隐，不必永远以退隐证明自己。</p><p>但这并不要求：</p><p><strong>任何时候都应留下，或任何时候都应离开。</strong></p><p><strong>合宜的行为需要面对情境，不只维持既有姿态。</strong></p><h4 id="顺人不是无条件服从" tabindex="-1">顺人不是无条件服从 <a class="header-anchor" href="#顺人不是无条件服从" aria-label="Permalink to &quot;顺人不是无条件服从&quot;">​</a></h4><p>可以沟通、调整、合作。</p><p>也可以拒绝不当要求、保持距离或退出关系。</p><p>这些现代引申需要具体判断，不以一句顺人取消边界。</p><h3 id="六彻与心有天游" tabindex="-1">六彻与心有天游 <a class="header-anchor" href="#六彻与心有天游" aria-label="Permalink to &quot;六彻与心有天游&quot;">​</a></h3><h4 id="原文-7" tabindex="-1">原文 <a class="header-anchor" href="#原文-7" aria-label="Permalink to &quot;原文&quot;">​</a></h4>',12)),a(s,{sections:z,glossary:T,"default-mode":"classic","aria-label":"外物·六彻与心有天游 原文"}),n[35]||(n[35]=t("blockquote",null,[t("p",null,"**文字说明：**颤、跈等保留来稿。彼教不学、胞有重阆及末句均有训释问题，不强作唯一解释。"),t("p",null,"气息、孔窍与壅塞属于古代生命论语境，不直接对应现代医学，也不将所有痛苦归责于个人。")],-1)),n[36]||(n[36]=t("h4",{id:"生僻字词-8",tabindex:"-1"},[e("生僻字词 "),t("a",{class:"header-anchor",href:"#生僻字词-8","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(d,{items:[{term:"彻",pinyin:["chè"],meaning:"通达。"},{term:"壅",pinyin:["yōng"],meaning:"堵塞。"},{term:"哽",pinyin:["gěng"],meaning:"梗阻、不通等。"},{term:"窦",pinyin:["dòu"],meaning:"孔窍、通道。"},{term:"天游",pinyin:["tiān","yóu"],meaning:"心的自然游动、未被拘塞的状态等。"},{term:"勃谿",pinyin:["bó","xī"],meaning:"争执。"},{term:"相攘",pinyin:["xiāng","rǎng"],meaning:"相争、相扰等。"}]}),n[37]||(n[37]=t("h4",{id:"核心句引读-8",tabindex:"-1"},[e("核心句引读 "),t("a",{class:"header-anchor",href:"#核心句引读-8","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(r,{title:"通达需要余地，不必把每一处空间填满",subtitle:"减少壅塞，不等于取消感知、认识与现实支持。",lines:[{text:"彼教不学，承意不彼。",tone:"存疑",guide:"句法与所指有不同解释，暂不逐字定译。不能仅据不学二字宣布所有教学有害，也不补成某种确定的忘言方法。"},{text:"目彻为明……心彻为知，知彻为德。",tone:"六彻",guide:"反复以彻连接功能与所成，可先把握通达。颤及德的细义仍待辨，不解释成六种神秘修炼，也不建成现代神经功能模型。"},{text:"凡道不欲壅。",tone:"通路",guide:"联系孔窍、气息，道可有通路意味。壅塞的比喻可以帮助理解受阻，但不将每个字对应成疾病进展。"},{text:"其不殷，非天之罪。",tone:"归责限制",guide:"在本段古代论述中反省人为妨碍，不能扩成任何疾病都由个人造成。先天差异、外部伤害与复杂病因不能被这句抹去。"},{text:"人则顾塞其窦。",tone:"反而堵塞",guide:"写已有通道反被堵住，可联想欲求、成见等，但原文未逐项列因。不能凭比喻给读者诊断，也不要求停止必要治疗。"},{text:"室无空虚，则妇姑勃谿。",tone:"居室譬喻",guide:"以缺少空间写摩擦，不是家庭冲突的完整社会解释。不能将责任固定给婆婆、媳妇或住房面积单一因素。"},{text:"心无天游，则六凿相攘。",tone:"心的余地",guide:"功能相争与心无游动余地并置，不等于心应什么都没有。可以关注不被单一执著完全占满，不必取消感知与思考。"},{text:"亦神者不胜。",tone:"末句存疑",guide:"可有精神未能承受山林之益等理解，但不强定。外部环境有益与心的通达可以一起讨论，不让一种读法冒充唯一原意。"}]}),n[38]||(n[38]=i(`<h4 id="六彻-不只靠不断增加" tabindex="-1">六彻，不只靠不断增加 <a class="header-anchor" href="#六彻-不只靠不断增加" aria-label="Permalink to &quot;六彻，不只靠不断增加&quot;">​</a></h4><p>本节可以关注：</p><p><strong>功能是否有通达的条件？</strong></p><p>而不只问：</p><p><strong>还能给自己增加什么任务、方法与要求？</strong></p><p>但不能将通达简化为：</p><p><strong>所有外在帮助都应撤去。</strong></p><p>环境、交往、教育与医疗支持，是否适宜仍需具体检查。</p><h4 id="土地、居室与心的余地" tabindex="-1">土地、居室与心的余地 <a class="header-anchor" href="#土地、居室与心的余地" aria-label="Permalink to &quot;土地、居室与心的余地&quot;">​</a></h4><table tabindex="0"><thead><tr><th>第七段</th><th>第八段「六彻与心有天游」</th></tr></thead><tbody><tr><td>未被直接踩踏的土地</td><td>未被占满的居室与心</td></tr><tr><td>支持立足的条件</td><td>提供周转与游动的余地</td></tr><tr><td>直接用途不能覆盖全部依赖</td><td>持续活动不能耗尽全部空间</td></tr></tbody></table><p>这是段内的阅读联系，不表示土地、居室与心属于同一套严格模型。</p><p><strong>余地不必是行动的敌人，也可能是合宜行动的条件。</strong></p><h2 id="第五至第八段·阶段性脉络" tabindex="-1">第五至第八段·阶段性脉络 <a class="header-anchor" href="#第五至第八段·阶段性脉络" aria-label="Permalink to &quot;第五至第八段·阶段性脉络&quot;">​</a></h2><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>第5段·老莱子与仲尼（节引）</span></span>
<span class="line"><span>    操心天下的神情</span></span>
<span class="line"><span>    → 去躬矜与容知</span></span>
<span class="line"><span>    → 眼前与长远后果</span></span>
<span class="line"><span>    → 名号牵引与誉非</span></span>
<span class="line"><span>    → 仍可兴事，回看自矜</span></span>
<span class="line"><span></span></span>
<span class="line"><span>第6段·宋元君神龟</span></span>
<span class="line"><span>    异能与被捕同时成立</span></span>
<span class="line"><span>    → 献龟，生死由他人决定</span></span>
<span class="line"><span>    → 对使用者之吉，对龟之害</span></span>
<span class="line"><span>    → 能知不等于能自保</span></span>
<span class="line"><span>    → 放下小知与刻意经营</span></span>
<span class="line"><span>    → 自然成长仍有交往条件</span></span>
<span class="line"><span></span></span>
<span class="line"><span>第7段·无用之用</span></span>
<span class="line"><span>    惠子判断言论无用</span></span>
<span class="line"><span>    → 直接占用仅容足</span></span>
<span class="line"><span>    → 删除周围的设想</span></span>
<span class="line"><span>    → 看见未被计入的支持条件</span></span>
<span class="line"><span></span></span>
<span class="line"><span>第8段·游于世而不僻</span></span>
<span class="line"><span>    游不只由行迹决定</span></span>
<span class="line"><span>    → 身份与时势</span></span>
<span class="line"><span>    → 不固守古今与旧有行为</span></span>
<span class="line"><span>    → 顺人而不失己</span></span>
<span class="line"><span></span></span>
<span class="line"><span>第8段·六彻与心有天游</span></span>
<span class="line"><span>    六彻</span></span>
<span class="line"><span>    → 道不欲壅</span></span>
<span class="line"><span>    → 孔窍与人为堵塞</span></span>
<span class="line"><span>    → 居室空间与心有天游</span></span>
<span class="line"><span>    → 末句保留存疑</span></span></code></pre></div><h3 id="阶段性三问-1" tabindex="-1">阶段性三问 <a class="header-anchor" href="#阶段性三问-1" aria-label="Permalink to &quot;阶段性三问&quot;">​</a></h3><h4 id="第一问-善与知是否变成了安排一切的资格" tabindex="-1">第一问：善与知是否变成了安排一切的资格？ <a class="header-anchor" href="#第一问-善与知是否变成了安排一切的资格" aria-label="Permalink to &quot;第一问：善与知是否变成了安排一切的资格？&quot;">​</a></h4><p>有善意，不免除对方法与后果的检查。</p><p>有智慧，不保证能够控制所有回应。</p><h4 id="第二问-我是否把直接用途-误认成全部条件" tabindex="-1">第二问：我是否把直接用途，误认成全部条件？ <a class="header-anchor" href="#第二问-我是否把直接用途-误认成全部条件" aria-label="Permalink to &quot;第二问：我是否把直接用途，误认成全部条件？&quot;">​</a></h4><p>未被直接占用、未有即时产出的部分，不一定可以删除。</p><h4 id="第三问-我的处世与认识-还有调整的余地吗" tabindex="-1">第三问：我的处世与认识，还有调整的余地吗？ <a class="header-anchor" href="#第三问-我的处世与认识-还有调整的余地吗" aria-label="Permalink to &quot;第三问：我的处世与认识，还有调整的余地吗？&quot;">​</a></h4><p>不固守身份与行迹，也不把心完全交给任务、刺激与评价。</p><h3 id="阶段性收束-1" tabindex="-1">阶段性收束 <a class="header-anchor" href="#阶段性收束-1" aria-label="Permalink to &quot;阶段性收束&quot;">​</a></h3><blockquote><p><strong>善与知不授予安排一切的权利，也不保证免于灾祸；行动与认识仍需要适宜条件，以及未被占满的余地。</strong></p></blockquote><p>这是这几段的串读线索，不是全篇唯一主旨。</p><h3 id="德名、劳佚与外在惊叹" tabindex="-1">德名、劳佚与外在惊叹 <a class="header-anchor" href="#德名、劳佚与外在惊叹" aria-label="Permalink to &quot;德名、劳佚与外在惊叹&quot;">​</a></h3><h4 id="原文-8" tabindex="-1">原文 <a class="header-anchor" href="#原文-8" aria-label="Permalink to &quot;原文&quot;">​</a></h4>`,27)),a(s,{sections:j,glossary:S,"default-mode":"classic","aria-label":"外物·德名与劳佚 原文"}),n[39]||(n[39]=t("blockquote",null,[t("p",null,"**文字说明：**德溢乎名、草木之倒植者及非佚者之所未尝过而问焉等存在训释、句法难点。"),t("p",null,"本节保留论述的跳跃性，不整理成德、名、暴、谋、知、争必然依次退化的理论。")],-1)),n[40]||(n[40]=t("h4",{id:"生僻字词-9",tabindex:"-1"},[e("生僻字词 "),t("a",{class:"header-anchor",href:"#生僻字词-9","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(d,{items:[{term:"誸",pinyin:["xián"],meaning:"迫急、紧迫等。"},{term:"柴",pinyin:["zhài"],meaning:"此处通常联系闭塞、阻隔。"},{term:"怒生",pinyin:["nù","shēng"],meaning:"蓬勃生长。"},{term:"铫鎒",pinyin:["yáo","nòu"],meaning:"锄耨一类农具，字形音义待统一。"},{term:"佚者",pinyin:["yì","zhě"],meaning:"安逸、自在者等。"},{term:"遽",pinyin:["jù"],meaning:"急迫。"},{term:"骇",pinyin:["hài"],meaning:"使人惊异、震动。"}]}),n[41]||(n[41]=t("h4",{id:"核心句引读-9",tabindex:"-1"},[e("核心句引读 "),t("a",{class:"header-anchor",href:"#核心句引读-9","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(r,{title:"不以名声与惊叹替代内在所得",subtitle:"关系短句不等于单线退化史，休养也不因被称劳者之务而失去价值。",lines:[{text:"德溢乎名，名溢乎暴。",tone:"德与名",guide:"溢与暴的关系仍需辨析，不先把暴定为暴力。可以讨论内在所得与外在显露的区别，不能仅凭词序推出德必然退化为暴。"},{text:"柴生乎守。",tone:"固守与闭塞",guide:"可与道不欲壅、不留行对读，反省过度执守造成的阻隔。不能扩大成所有坚持、承诺与原则都有害，仍需看坚持什么、如何坚持。"},{text:"官事果乎众宜。",tone:"条件",guide:"众宜可联系多方面合宜，不只等同多数赞同。事务完成需要条件，也不保证条件看似适宜便必定成功。"},{text:"草木之倒植者过半而不知其然。",tone:"不同视角",guide:"倒植及整句关系有争议，可保留生长与锄治并置的反差。不能据此认定庄子反对一切农业，也不补出唯一政治象征。"},{text:"静默可以补病……宁可以止遽。",tone:"修补",guide:"承认静养、安宁等可能有作用，但古代调养语句不作为现代疗效保证。眦媙不强行对应按摩或某种治疗。"},{text:"若是劳者之务也。",tone:"劳与佚",guide:"可区别受扰后的修补与不以劳扰为中心的生活，后句仍有句法疑义。不能贬低病者、老者求助，也不把需要休养当作修养低下。"},{text:"圣人之所以骇天下，神人未尝过而问焉。",tone:"外部惊叹",guide:"使天下惊异并不自动成为另一人物的关切。不能据此建立全书统一等级，或鼓励轻蔑他人成就。"},{text:"小人所以合时，君子未尝过而问焉。",tone:"合时",guide:"限制以时俗认可作最终尺度，不是任何合乎时代的行为都错误。是否值得追求，需要看其实际意义与代价。"}]}),n[42]||(n[42]=i('<h4 id="开头六句不是同一种关系" tabindex="-1">开头六句不是同一种关系 <a class="header-anchor" href="#开头六句不是同一种关系" aria-label="Permalink to &quot;开头六句不是同一种关系&quot;">​</a></h4><table tabindex="0"><thead><tr><th>表述</th><th>不宜直接改写为</th></tr></thead><tbody><tr><td>溢乎</td><td>前一项必然退化成后一项</td></tr><tr><td>稽乎</td><td>唯一的产生原因</td></tr><tr><td>出乎</td><td>所有知识都来自争夺</td></tr><tr><td>生乎</td><td>所有坚持都造成闭塞</td></tr><tr><td>果乎</td><td>多数赞同便保证完成</td></tr></tbody></table><p><strong>先保留句法差异，再讨论可能的思想联系。</strong></p><h4 id="休养可以有用-不必成为全部生活" tabindex="-1">休养可以有用，不必成为全部生活 <a class="header-anchor" href="#休养可以有用-不必成为全部生活" aria-label="Permalink to &quot;休养可以有用，不必成为全部生活&quot;">​</a></h4><p>本节承认静默、安宁等修补方式。</p><p>不能反过来要求：</p><p><strong>真正自在的人不应生病、不需休息，也不该求助。</strong></p><p>劳与佚在此是阅读上的对照，不是给病者与老者排定价值高下。</p><h4 id="惊叹范围不等于价值尺度" tabindex="-1">惊叹范围不等于价值尺度 <a class="header-anchor" href="#惊叹范围不等于价值尺度" aria-label="Permalink to &quot;惊叹范围不等于价值尺度&quot;">​</a></h4><p>合时、骇国、骇世、骇天下，都涉及外部反应。</p><p>可以有成就，也不必把不断扩大惊叹者的范围，变成必须完成的生命任务。</p><p><strong>不追逐惊叹，不等于否定所有成就。</strong></p><h2 id="九、哀毁与效仿·奖励、称扬与伤生" tabindex="-1">九、哀毁与效仿·奖励、称扬与伤生 <a class="header-anchor" href="#九、哀毁与效仿·奖励、称扬与伤生" aria-label="Permalink to &quot;九、哀毁与效仿·奖励、称扬与伤生&quot;">​</a></h2><h3 id="原文-9" tabindex="-1">原文 <a class="header-anchor" href="#原文-9" aria-label="Permalink to &quot;原文&quot;">​</a></h3>',14)),a(s,{sections:A,glossary:C,"default-mode":"classic","aria-label":"外物·哀毁与效仿 原文"}),n[43]||(n[43]=t("blockquote",null,[t("p",null,"**阅读说明：**善毁爵为官师、蹲于窾水保留断句与音义疑问。"),t("p",null,"死亡与投水属于寓言叙事，不作为高洁证明或值得效仿的行动。人物动机不能由简略文字全部复原。")],-1)),n[44]||(n[44]=t("h3",{id:"生僻字词-10",tabindex:"-1"},[e("生僻字词 "),t("a",{class:"header-anchor",href:"#生僻字词-10","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(d,{items:[{term:"善毁",pinyin:["shàn","huǐ"],meaning:"居丧哀毁、形体损伤等。"},{term:"党人",pinyin:["dǎng","rén"],meaning:"同乡或同一群体，不是现代政党成员。"},{term:"帅",pinyin:["shuài"],meaning:"联系率领。"},{term:"窾水",pinyin:["kuǎn","shuǐ"],meaning:"水名。"},{term:"吊",pinyin:["diào"],meaning:"吊唁、哀悼。"},{term:"踣",pinyin:["bó"],meaning:"仆倒，此处联系投河。"}]}),n[45]||(n[45]=t("h3",{id:"核心句引读-10",tabindex:"-1"},[e("核心句引读 "),t("a",{class:"header-anchor",href:"#核心句引读-10","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(r,{title:"被奖励、被称扬的行迹，也需要检查生命代价",subtitle:"哀悼与拒绝可以保留，毁身不必成为证明价值的任务。",lines:[{text:"以善毁爵为官师。",tone:"奖励",guide:"通常联系因哀毁表现而获授官职，具体断句仍需校读。问题不只是个体哀痛，而是何种表现被公共奖励。"},{text:"其党人毁而死者半。",tone:"效仿",guide:"以强烈后果写奖励与群体行为的关系，不作历史统计。不能据此否定哀悼本身，也不要求丧亲者以更深伤身证明真情。"},{text:"许由逃之……务光怒之。",tone:"可以拒绝",guide:"天下被给予，并不意味着受让者必须接受。不能补定二人都在揭穿虚伪让位，也不把拒绝一切权位立成普遍义务。"},{text:"纪他闻之，帅弟子而蹲于窾水。",tone:"极端行迹",guide:"通常联系投水，人物究竟为何如此并未充分交代。不能仅以闻之断定所有人都是邀名，也不能将行动当作高洁模板。"},{text:"诸侯吊之。",tone:"社会回应",guide:"死亡受到吊唁，不自动证明死亡应被复制。哀悼逝者与赞成后来者采取同样行动，是两件不同的事。"},{text:"申徒狄因以踣河。",tone:"后续",guide:"叙事写后续投河，可与前文效仿问题对读，但不补造完整心理与因果过程。不以生命损伤作为德性成立的条件。"}]}),n[46]||(n[46]=i(`<h3 id="表现如何反过来支配情感" tabindex="-1">表现如何反过来支配情感 <a class="header-anchor" href="#表现如何反过来支配情感" aria-label="Permalink to &quot;表现如何反过来支配情感&quot;">​</a></h3><p>演门故事可按以下关系阅读：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>丧亲与哀痛</span></span>
<span class="line"><span>    → 哀毁表现获得奖励</span></span>
<span class="line"><span>    → 群体追随这种表现</span></span>
<span class="line"><span>    → 表现强度取代实际情感</span></span>
<span class="line"><span>    → 生命受到损伤</span></span></code></pre></div><p>这是编辑性的梳理，不将每位效仿者的动机都确定为求官。</p><p><strong>真切哀悼，不需要用身体毁损来兑换认可。</strong></p><h3 id="拒绝不等于必须毁身" tabindex="-1">拒绝不等于必须毁身 <a class="header-anchor" href="#拒绝不等于必须毁身" aria-label="Permalink to &quot;拒绝不等于必须毁身&quot;">​</a></h3><p>许由逃、务光怒与后续投水并列。</p><p>可以拒绝不合己意的安排，却不必把他人的极端行迹变成自己的道德任务。</p><p><strong>一种行为有高洁名号，也不能免除对后果的检查。</strong></p><h3 id="与篇首连读" tabindex="-1">与篇首连读 <a class="header-anchor" href="#与篇首连读" aria-label="Permalink to &quot;与篇首连读&quot;">​</a></h3><table tabindex="0"><thead><tr><th>篇首</th><th>第九段</th></tr></thead><tbody><tr><td>忠未必信、孝未必爱</td><td>获得奖励也可能引发伤生</td></tr><tr><td>行为不能保证外在回应</td><td>外在回应不能保证行为正当</td></tr><tr><td>不把认可当作必然</td><td>不把认可当作最终尺度</td></tr></tbody></table><p><strong>没有被认可，不证明行为无价值；获得认可，也不证明值得继续加码。</strong></p><h2 id="十、得意忘言·器具、意旨与交流" tabindex="-1">十、得意忘言·器具、意旨与交流 <a class="header-anchor" href="#十、得意忘言·器具、意旨与交流" aria-label="Permalink to &quot;十、得意忘言·器具、意旨与交流&quot;">​</a></h2><h3 id="原文-10" tabindex="-1">原文 <a class="header-anchor" href="#原文-10" aria-label="Permalink to &quot;原文&quot;">​</a></h3>`,14)),a(s,{sections:V,glossary:I,"default-mode":"classic","aria-label":"外物·得意忘言 原文"}),n[47]||(n[47]=t("blockquote",null,[t("p",null,"**文字说明：**荃沿用来稿，其他文本有作筌者。"),t("p",null,"得意指领会意旨，不是得意自满。忘言不等于拒绝读书、停止解释，或自称悟意便不必校正误读。")],-1)),n[48]||(n[48]=t("h3",{id:"生僻字词-11",tabindex:"-1"},[e("生僻字词 "),t("a",{class:"header-anchor",href:"#生僻字词-11","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(d,{items:[{term:"荃",pinyin:["quán"],meaning:"通常联系筌、捕鱼器具。"},{term:"蹄",pinyin:["tí"],meaning:"捕兔器具，不是兔足。"},{term:"意",pinyin:["yì"],meaning:"意旨、所表达与领会的内容。"},{term:"得意",pinyin:["dé","yì"],meaning:"领会意旨。"},{term:"忘言",pinyin:["wàng","yán"],meaning:"不执著言辞等，不等于不能交谈。"}]}),n[49]||(n[49]=t("h3",{id:"核心句引读-11",tabindex:"-1"},[e("核心句引读 "),t("a",{class:"header-anchor",href:"#核心句引读-11","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(r,{title:"借助言辞，也不让言辞取代所要领会的内容",subtitle:"篇末仍欲与之言，忘言不是终止交流。",lines:[{text:"得鱼而忘荃；得兔而忘蹄。",tone:"器具与所求",guide:"器具服务于所求，不宜反过来把器具当作唯一中心。忘不必是毁坏、丢弃，也不意味着今后永远无需使用。"},{text:"言者所以在意。",tone:"语言作用",guide:"首先承认言语能够帮助领会意旨，不能只留下忘言而删除语言作用。工具比喻也不必穷尽语言的所有功能。"},{text:"得意而忘言。",tone:"不执形式",guide:"可理解为领会后不固守言辞形式，不是跳过文字随意发挥。理解仍需接受语境、原文与事实的检验。"},{text:"忘言之人而与之言哉！",tone:"仍欲交流",guide:"寻找忘言者，却仍想交谈，形成鲜明反常意味。不能把忘言简单等同沉默，也不将其变成拒绝解释的高明姿态。"}]}),n[50]||(n[50]=i(`<h3 id="器具与所求" tabindex="-1">器具与所求 <a class="header-anchor" href="#器具与所求" aria-label="Permalink to &quot;器具与所求&quot;">​</a></h3><table tabindex="0"><thead><tr><th>借助</th><th>所在</th></tr></thead><tbody><tr><td>荃</td><td>鱼</td></tr><tr><td>蹄</td><td>兔</td></tr><tr><td>言</td><td>意</td></tr></tbody></table><p>可以使用器具，也不把器具取代所得。</p><p>可以认真辨字、解释与讨论，也不把某一种说法固定为永远不可改变的形式。</p><p><strong>不执著言辞，不等于不尊重文字。</strong></p><h3 id="忘言不能用来掩盖误读" tabindex="-1">忘言不能用来掩盖误读 <a class="header-anchor" href="#忘言不能用来掩盖误读" aria-label="Permalink to &quot;忘言不能用来掩盖误读&quot;">​</a></h3><p>未知字义，需要辨字。</p><p>未明语境，需要读上下文。</p><p>理解受到反例挑战，需要说明或修正。</p><p>不能只说：</p><p><strong>我已得意，所以不必管原文。</strong></p><p><strong>忘言松开的是执著，不是检验。</strong></p><h3 id="与《则阳》篇末的联系与区别" tabindex="-1">与《则阳》篇末的联系与区别 <a class="header-anchor" href="#与《则阳》篇末的联系与区别" aria-label="Permalink to &quot;与《则阳》篇末的联系与区别&quot;">​</a></h3><table tabindex="0"><thead><tr><th>《则阳》</th><th>《外物》</th></tr></thead><tbody><tr><td>言默不足以载</td><td>言者所以在意</td></tr><tr><td>议论有其限度</td><td>器具不能取代所求</td></tr><tr><td>沉默也不保证穷尽道</td><td>忘言仍可与人交谈</td></tr></tbody></table><p>两篇都不能仅归结为：</p><p><strong>道不可说，所以停止说话。</strong></p><p>《外物》尤其保留了：</p><p><strong>寻找能够交流的对话者。</strong></p><h2 id="全篇脉络·十段阅读地图" tabindex="-1">全篇脉络·十段阅读地图 <a class="header-anchor" href="#全篇脉络·十段阅读地图" aria-label="Permalink to &quot;全篇脉络·十段阅读地图&quot;">​</a></h2><blockquote><p>十段及第八段分节为项目阅读整理，不是原文固定章节标题。</p><p>第五段连续原文尚待补齐；以下地图依据已收到的原文、节引与解读建立。</p></blockquote><table tabindex="0"><thead><tr><th>段落</th><th>场景或论题</th><th>核心问题</th></tr></thead><tbody><tr><td>一</td><td>忠孝遭遇、利害焚和</td><td>行为能否保证回应？</td></tr><tr><td>二</td><td>庄周贷粟、涸辙之鲋</td><td>帮助是否及时而适宜？</td></tr><tr><td>三</td><td>任公子大钓</td><td>方法是否与对象相称？</td></tr><tr><td>四</td><td>儒者发冢</td><td>经典说辞实际服务于什么？</td></tr><tr><td>五</td><td>老莱子教仲尼</td><td>善与知是否夹带自矜？</td></tr><tr><td>六</td><td>宋元君神龟</td><td>出众能力能保证什么？</td></tr><tr><td>七</td><td>惠庄论无用</td><td>直接用途是否覆盖全部条件？</td></tr><tr><td>八·一</td><td>游世、不留行</td><td>能否适应而不失己？</td></tr><tr><td>八·二</td><td>六彻、心有天游</td><td>生命与认识是否还有余地？</td></tr><tr><td>八·三</td><td>德名、劳佚与惊叹</td><td>名声与成就是否成为唯一尺度？</td></tr><tr><td>九</td><td>哀毁、拒绝与投水</td><td>认可与效仿是否伤生？</td></tr><tr><td>十</td><td>得意忘言</td><td>言辞能否帮助理解而不取代意义？</td></tr></tbody></table><h3 id="一条串读线索" tabindex="-1">一条串读线索 <a class="header-anchor" href="#一条串读线索" aria-label="Permalink to &quot;一条串读线索&quot;">​</a></h3><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>外物不可必</span></span>
<span class="line"><span>    → 行为、能力与外部回应不能完全等同</span></span>
<span class="line"><span></span></span>
<span class="line"><span>及时而适宜</span></span>
<span class="line"><span>    → 小水与大钓各有对象和条件</span></span>
<span class="line"><span></span></span>
<span class="line"><span>检验言行</span></span>
<span class="line"><span>    → 名号、经典与说辞不保证实际正当</span></span>
<span class="line"><span></span></span>
<span class="line"><span>反省善知</span></span>
<span class="line"><span>    → 不自矜，也不要求智慧保证一切</span></span>
<span class="line"><span></span></span>
<span class="line"><span>看见支持条件</span></span>
<span class="line"><span>    → 不删除全部无用，不耗尽心的余地</span></span>
<span class="line"><span></span></span>
<span class="line"><span>不以名迹伤生</span></span>
<span class="line"><span>    → 外在认可不成为必须加码的任务</span></span>
<span class="line"><span></span></span>
<span class="line"><span>得意忘言</span></span>
<span class="line"><span>    → 借助表达，而不以表达取代理解</span></span></code></pre></div><p>全篇不是严格依次升级的修养阶梯。</p><p>更适合看作一组互相照映的故事与短论：</p><p><strong>外物怎样成为帮助、条件、危险、评价与拘束？人又怎样与之相处？</strong></p><h2 id="三问解读" tabindex="-1">三问解读 <a class="header-anchor" href="#三问解读" aria-label="Permalink to &quot;三问解读&quot;">​</a></h2><h3 id="第一问-我是否要求行为与能力保证所有结果" tabindex="-1">第一问：我是否要求行为与能力保证所有结果？ <a class="header-anchor" href="#第一问-我是否要求行为与能力保证所有结果" aria-label="Permalink to &quot;第一问：我是否要求行为与能力保证所有结果？&quot;">​</a></h3><p>忠不保证被信，孝不保证被爱。</p><p>神龟的异能不保证自保。</p><p>任公子的等待，也不构成普遍成功公式。</p><p>可以努力、求助与保护自己，同时承认不能完全控制的部分。</p><p><strong>承认限度，不是放弃行动，更不是替加害者免责。</strong></p><h3 id="第二问-我是否只看直接用途与外在认可" tabindex="-1">第二问：我是否只看直接用途与外在认可？ <a class="header-anchor" href="#第二问-我是否只看直接用途与外在认可" aria-label="Permalink to &quot;第二问：我是否只看直接用途与外在认可？&quot;">​</a></h3><p>斗升之水可以及时救急。</p><p>大鱼需要与之相称的方法。</p><p>脚外的土地也参与立足条件。</p><p>名声、惊叹与奖励，却不能自动证明价值。</p><p><strong>用途需要看关系，认可需要看代价。</strong></p><h3 id="第三问-我是否让形式取代了所要关切的内容" tabindex="-1">第三问：我是否让形式取代了所要关切的内容？ <a class="header-anchor" href="#第三问-我是否让形式取代了所要关切的内容" aria-label="Permalink to &quot;第三问：我是否让形式取代了所要关切的内容？&quot;">​</a></h3><p>引用诗礼不等于尊重死者。</p><p>表现哀毁不等于真情更深。</p><p>固守高洁行迹不等于理解其精神。</p><p>固守一句话也不等于领会意旨。</p><p><strong>称号、行迹与言辞可以传达，却不能自动取代德性、情感与理解。</strong></p><h2 id="现代思考与启发" tabindex="-1">现代思考与启发 <a class="header-anchor" href="#现代思考与启发" aria-label="Permalink to &quot;现代思考与启发&quot;">​</a></h2><blockquote><p>以下为现代引申，不是原文已经提出的医学、心理学或管理学理论。</p></blockquote><h3 id="一、帮助-先问当前需要" tabindex="-1">一、帮助：先问当前需要 <a class="header-anchor" href="#一、帮助-先问当前需要" aria-label="Permalink to &quot;一、帮助：先问当前需要&quot;">​</a></h3><p>承诺不只看数量，还要看时机、可落实程度与对象所需。</p><p>若不能立即提供帮助，应把限制说清楚，不用远期宏大计划冒充当前解决方案。</p><h3 id="二、行动-检查方法范围" tabindex="-1">二、行动：检查方法范围 <a class="header-anchor" href="#二、行动-检查方法范围" aria-label="Permalink to &quot;二、行动：检查方法范围&quot;">​</a></h3><p>大投入不自动正确，小方法也不天然无用。</p><p>先问对象、目标、期限与代价，再判断方法是否相称。</p><p>持续投入可以有价值，也需要允许重新评估与退出。</p><h3 id="三、关系-付出不是兑换券" tabindex="-1">三、关系：付出不是兑换券 <a class="header-anchor" href="#三、关系-付出不是兑换券" aria-label="Permalink to &quot;三、关系：付出不是兑换券&quot;">​</a></h3><p>善意与努力不能保证得到信任、爱或认可。</p><p>这不要求无限加码，也不说明受伤者应独自承担责任。</p><p>必要的边界、支持与保护仍有位置。</p><h3 id="四、评价-不要奖励伤生的表现" tabindex="-1">四、评价：不要奖励伤生的表现 <a class="header-anchor" href="#四、评价-不要奖励伤生的表现" aria-label="Permalink to &quot;四、评价：不要奖励伤生的表现&quot;">​</a></h3><p>若奖励只关注可见的牺牲程度，可能诱发加码、失真与效仿。</p><p>应检查：</p><ul><li>行为是否真的实现关切。</li><li>是否损害生命与基本生活。</li><li>是否提供更安全的表达方式。</li><li>公共称扬是否被误当作普遍义务。</li></ul><p><strong>不能要求伤害自己来证明忠诚、孝心或高洁。</strong></p><h3 id="五、空间-保留未被任务占满的余地" tabindex="-1">五、空间：保留未被任务占满的余地 <a class="header-anchor" href="#五、空间-保留未被任务占满的余地" aria-label="Permalink to &quot;五、空间：保留未被任务占满的余地&quot;">​</a></h3><p>休息、周转空间与注意力余地，不必都以即时产出证明价值。</p><p>它们可能支持判断与行动。</p><p>这不是所有未使用资源都应永久保留，而是删除之前先检查关系。</p><h3 id="六、身心-不以哲学归责疾病" tabindex="-1">六、身心：不以哲学归责疾病 <a class="header-anchor" href="#六、身心-不以哲学归责疾病" aria-label="Permalink to &quot;六、身心：不以哲学归责疾病&quot;">​</a></h3><p>焚和、壅塞、补病等是古代论述与比喻。</p><p>不能据此认定疾病来自失德、不会虚静或个人自堵。</p><p>现实病痛应获得适当评估、照料与支持。</p><h3 id="七、交流-意义不能成为拒绝解释的理由" tabindex="-1">七、交流：意义不能成为拒绝解释的理由 <a class="header-anchor" href="#七、交流-意义不能成为拒绝解释的理由" aria-label="Permalink to &quot;七、交流：意义不能成为拒绝解释的理由&quot;">​</a></h3><p>可以改变表达，也需要说明为何改变。</p><p>可以不争一句话的输赢，也不能忽视事实与逻辑。</p><p><strong>得意忘言不使任何人免于误读校正。</strong></p><h2 id="关键词索引" tabindex="-1">关键词索引 <a class="header-anchor" href="#关键词索引" aria-label="Permalink to &quot;关键词索引&quot;">​</a></h2><table tabindex="0"><thead><tr><th>关键词</th><th>所在</th><th>阅读提示</th></tr></thead><tbody><tr><td>外物不可必</td><td>一</td><td>不保证，不等于不能影响</td></tr><tr><td>忠未必信／孝未必爱</td><td>一</td><td>付出不自动兑换回应</td></tr><tr><td>利害相摩／焚和</td><td>一</td><td>反省耗损，不替外部伤害免责</td></tr><tr><td>斗升之水</td><td>二</td><td>少而及时适宜</td></tr><tr><td>常与</td><td>二</td><td>生存依靠的条件</td></tr><tr><td>枯鱼之肆</td><td>二</td><td>迟到救助的反讽</td></tr><tr><td>大钩巨缁</td><td>三</td><td>方法与对象相称</td></tr><tr><td>期年不得鱼</td><td>三</td><td>不以即时成果作唯一判断</td></tr><tr><td>饰小说／县令</td><td>三</td><td>小言求名不等于大达</td></tr><tr><td>诗礼发冢</td><td>四</td><td>经典可能被用于掠夺</td></tr><tr><td>无伤口中珠</td><td>四</td><td>检查实际保护对象</td></tr><tr><td>躬矜／容知</td><td>五</td><td>反省自夸与智巧显露</td></tr><tr><td>两忘</td><td>五</td><td>不以誉非名号代替具体判断</td></tr><tr><td>踌躇以兴事</td><td>五</td><td>仍可行动，不保证每次成功</td></tr><tr><td>知有所困／神有所不及</td><td>六</td><td>能力不能覆盖全部处境</td></tr><tr><td>去小知／自善</td><td>六</td><td>不以局部经营自满</td></tr><tr><td>与能言者处</td><td>六</td><td>自然成长仍有条件</td></tr><tr><td>无用之用</td><td>七</td><td>直接用途之外的支持</td></tr><tr><td>不留行</td><td>八·一</td><td>不固定旧有行迹</td></tr><tr><td>顺人而不失己</td><td>八·一</td><td>相顺不等于无条件服从</td></tr><tr><td>彻／壅</td><td>八·二</td><td>通达与受阻</td></tr><tr><td>心有天游</td><td>八·二</td><td>心有未被占满的余地</td></tr><tr><td>六凿相攘</td><td>八·二</td><td>功能相争相扰</td></tr><tr><td>柴生乎守</td><td>八·三</td><td>固守可能形成闭塞</td></tr><tr><td>劳者／佚者</td><td>八·三</td><td>不以休养需要判高下</td></tr><tr><td>骇天下／合时</td><td>八·三</td><td>外部惊叹不是最终尺度</td></tr><tr><td>善毁／爵为官师</td><td>九</td><td>奖励如何影响表现</td></tr><tr><td>党人毁而死</td><td>九</td><td>认可可能引发伤生效仿</td></tr><tr><td>荃／蹄</td><td>十</td><td>器具与所求</td></tr><tr><td>得意／忘言</td><td>十</td><td>领会，不固守表达</td></tr><tr><td>与之言</td><td>十</td><td>篇末仍保留交流愿望</td></tr></tbody></table><h2 id="核心句速查" tabindex="-1">核心句速查 <a class="header-anchor" href="#核心句速查" aria-label="Permalink to &quot;核心句速查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>原句</th><th>所在</th><th>简要提示</th></tr></thead><tbody><tr><td>外物不可必。</td><td>一</td><td>不能保证全部外在结果</td></tr><tr><td>忠未必信……孝未必爱。</td><td>一</td><td>行为与回应有别</td></tr><tr><td>利害相摩，生火甚多，众人焚和。</td><td>一</td><td>利害牵动与耗损</td></tr><tr><td>我得斗升之水然活耳。</td><td>二</td><td>当前所需</td></tr><tr><td>曾不如早索我于枯鱼之肆。</td><td>二</td><td>远诺不能替代救急</td></tr><tr><td>旦旦而钓，期年不得鱼。</td><td>三</td><td>持续行动不等于即时成功</td></tr><tr><td>饰小说以干县令，其于大达亦远矣。</td><td>三</td><td>说辞求名不等于通达</td></tr><tr><td>儒以《诗》、《礼》发冢。</td><td>四</td><td>高尚语言与行为反差</td></tr><tr><td>无伤口中珠。</td><td>四</td><td>谨慎究竟保护谁</td></tr><tr><td>去汝躬矜与汝容知。</td><td>五</td><td>节引，连续原文待补</td></tr><tr><td>圣人踌躇以兴事。</td><td>五</td><td>仍有兴事的位置</td></tr><tr><td>知有所困，神有所不及也。</td><td>六</td><td>能力有其限度</td></tr><tr><td>婴儿生，无硕师而能言，与能言者处也。</td><td>六</td><td>成长依靠交往环境</td></tr><tr><td>知无用而始可与言用矣。</td><td>七</td><td>先检查用途标准</td></tr><tr><td>无用之为用也亦明矣。</td><td>七</td><td>被忽略的支持条件</td></tr><tr><td>至人不留行焉。</td><td>八·一</td><td>不固守行迹</td></tr><tr><td>顺人而不失己。</td><td>八·一</td><td>交往与保己</td></tr><tr><td>凡道不欲壅。</td><td>八·二</td><td>通达不宜受塞</td></tr><tr><td>心无天游，则六凿相攘。</td><td>八·二</td><td>心需要余地</td></tr><tr><td>柴生乎守。</td><td>八·三</td><td>执守与闭塞</td></tr><tr><td>其党人毁而死者半。</td><td>九</td><td>伤生效仿的警示</td></tr><tr><td>言者所以在意，得意而忘言。</td><td>十</td><td>言辞不取代意旨</td></tr><tr><td>吾安得夫忘言之人而与之言哉！</td><td>十</td><td>忘言仍欲交谈</td></tr></tbody></table><h2 id="与前篇的呼应" tabindex="-1">与前篇的呼应 <a class="header-anchor" href="#与前篇的呼应" aria-label="Permalink to &quot;与前篇的呼应&quot;">​</a></h2><ul><li><strong>《逍遥游》</strong>：惠子的大树与本篇的「无用之用」同源，都在追问「直接用途之外还有什么」；本篇更把问题落在周围未计入的支持条件上。</li><li><strong>《养生主》</strong>：「缘督以为经」保身全生，本篇第九段把这条线推到评价层面——被奖励的表现会反过来支配情感、伤及生命。</li><li><strong>《人间世》</strong>：处世、有用与征用，可与神龟一节参读：能知不等于能自保，被需要也不等于被善待。</li><li><strong>《德充符》</strong>：不以外在形貌与评价定人；本篇第八段「不以物易己」延续这一路。</li><li><strong>《山木》</strong>：材与不材之间仍未免累；本篇把「游于世而不僻，顺人而不失己」作为另一条出路。</li><li><strong>《庚桑楚》</strong>：「知止乎其所不能知」与本篇神龟、乃至第六、七段的「能力限度」互为注脚。</li><li><strong>《则阳》</strong>：言默不足以载，侧重议论与承载的限度；本篇「得意忘言」侧重器具、意旨与交流——两篇相接，一在「言不能尽」，一在「言可以借」。</li></ul><p>参读不等于各句完全同义，也不据此确定写作先后与直接影响。</p><h2 id="十段·一句话回顾" tabindex="-1">十段·一句话回顾 <a class="header-anchor" href="#十段·一句话回顾" aria-label="Permalink to &quot;十段·一句话回顾&quot;">​</a></h2><ol><li><strong>外物不可必</strong>：行为与回应之间，没有自动保证。</li><li><strong>庄周贷粟</strong>：帮助要看当前是否需要，不看承诺是否够大。</li><li><strong>任公子大钓</strong>：方法与对象要相称，小水钓不上大鱼。</li><li><strong>儒者发冢</strong>：会说正当的话，不等于正在做正当的事。</li><li><strong>老莱子与仲尼</strong>：善与知一旦夹带自矜，就成了新的负担。</li><li><strong>宋元君神龟</strong>：出众的能力不保证安全，也不保证被善待。</li><li><strong>无用之用</strong>：直接用途之外，还有被忽略的支持条件。</li><li><strong>游世与天游</strong>（三节）：适应处境而不失自身；心需要未被占满的余地；名声与外部惊叹不是最终尺度。</li><li><strong>哀毁与效仿</strong>：被奖励的表现，会反过来支配情感。</li><li><strong>得意忘言</strong>：借言辞抵达意旨，而不以言辞取代意旨。</li></ol><h2 id="一句话读懂《外物》" tabindex="-1">一句话读懂《外物》 <a class="header-anchor" href="#一句话读懂《外物》" aria-label="Permalink to &quot;一句话读懂《外物》&quot;">​</a></h2><blockquote><p><strong>「外物不可必。」</strong></p></blockquote><p>这句是全篇的起点：行为、能力、承诺与他人的回应，都不能兑换成保证。能做的是把方法与对象核对，把空间留给生命本身——到了篇末，就成了「得意而忘言」：连最靠得住的表达，也只是通往意旨的器具。</p><h2 id="校读与合并说明" tabindex="-1">校读与合并说明 <a class="header-anchor" href="#校读与合并说明" aria-label="Permalink to &quot;校读与合并说明&quot;">​</a></h2><h3 id="一、篇目归属" tabindex="-1">一、篇目归属 <a class="header-anchor" href="#一、篇目归属" aria-label="Permalink to &quot;一、篇目归属&quot;">​</a></h3><p><strong>《外物》为《庄子》第二十六篇，属于杂篇。</strong></p><p>不使用《山木》的标题、变量或篇目来源。</p><h3 id="二、当前原文状态" tabindex="-1">二、当前原文状态 <a class="header-anchor" href="#二、当前原文状态" aria-label="Permalink to &quot;二、当前原文状态&quot;">​</a></h3><ul><li>第一至第四段：依来稿整理。</li><li>第五段：仅为关键节引，连续全文待补。</li><li>第六段：无遗囗、无遗生筴等待核对。</li><li>第七段：依来稿整理。</li><li>第八段：三节（游世、六彻、德名）均已整理。</li><li>第九、第十段：依来稿整理。</li></ul><p><strong>篇末栏目已建立，但不能标作全部原文校定完成。</strong></p><h3 id="三、疑难文字" tabindex="-1">三、疑难文字 <a class="header-anchor" href="#三、疑难文字" aria-label="Permalink to &quot;三、疑难文字&quot;">​</a></h3><p>定稿时应选定底本，集中核对：</p><ul><li>第一段月、螴蜳、慰暋沈屯、僓。</li><li>第三段制河、揭竿累、县令。</li><li>第四段引号归属及故事中的引诗。</li><li>第五段完整正文、惠以欢为、以每成功等。</li><li>第六段无遗囗、无遗生筴、钻与筴。</li><li>第八段流遁、彼教不学、颤、跈、胞有重阆。</li><li>第八段末节暴、眦媙及劳佚句的否定关系。</li><li>第九段善毁爵为官师、蹲于窾水。</li><li>第十段荃／筌。</li><li>人物传说与故事细节不直接当作准确历史纪事。</li><li>忠孝与信爱的关系，不写成受害者应承担全部责任。</li><li>第二段不补定监河侯蓄意欺骗，也不说承诺已被证明未兑现。</li><li>第四段引诗不指认今本《诗经》篇目；对话归属保留说明。</li><li>跨篇对读是阅读参照，不宣称完全同义或确定的写作影响。</li></ul><p>不凭现代引申默默改写正文。</p><h3 id="四、跨篇参读" tabindex="-1">四、跨篇参读 <a class="header-anchor" href="#四、跨篇参读" aria-label="Permalink to &quot;四、跨篇参读&quot;">​</a></h3><ul><li>《则阳》的言默不足以载，侧重议论与承载的限度。</li><li>本篇得意忘言，侧重器具、意旨与交流。</li><li>《庚桑楚》的知止乎其所不能知，可与能力限度参读。</li><li>《人间世》的处世、有用与征用，可与神龟参读。</li><li>《逍遥游》的大用、用途与许由故事，可作比较。</li></ul><p>参读不等于各句完全同义，也不据此确定写作先后与直接影响。</p><h2 id="参考来源" tabindex="-1">参考来源 <a class="header-anchor" href="#参考来源" aria-label="Permalink to &quot;参考来源&quot;">​</a></h2><h3 id="本次直接依据" tabindex="-1">本次直接依据 <a class="header-anchor" href="#本次直接依据" aria-label="Permalink to &quot;本次直接依据&quot;">​</a></h3><ul><li>用户分批提供的《外物》原文、词条、分节解读与比较材料。</li><li>第五段依据用户提供的关键引句整理，未另行补造全文。</li></ul><h3 id="建议校读材料" tabindex="-1">建议校读材料 <a class="header-anchor" href="#建议校读材料" aria-label="Permalink to &quot;建议校读材料&quot;">​</a></h3><p>以下供选定底本与比较注释使用，不表示本页已逐条核完：</p><ul><li>郭庆藩《庄子集释》。</li><li>王先谦《庄子集解》。</li><li>陈鼓应《庄子今注今译》。</li></ul><p>正式发布时应补录实际使用的版本、出版信息及必要页码。</p><p><strong>当前属于来稿整理稿，不冒称已经完成校勘定本。</strong></p><h2 id="全篇最后一问" tabindex="-1">全篇最后一问 <a class="header-anchor" href="#全篇最后一问" aria-label="Permalink to &quot;全篇最后一问&quot;">​</a></h2><p>开篇问的是：</p><p><strong>行为能不能保证回应？</strong></p><p>中间转为：</p><p><strong>帮助与方法，是否适合当前对象？</strong></p><p>再转为：</p><p><strong>语言与能力，实际服务于谁？</strong></p><p>篇末停在：</p><p><strong>得意而忘言。</strong></p><p>于是最后可以这样问自己：</p><p><strong>我所依赖的那件「外物」，是帮助，还是已经成了我的尺度？</strong></p><p><strong>我给出的帮助，是对方此刻需要的吗？</strong></p><p><strong>我的能力与言辞，实际在为谁服务？</strong></p><p><strong>我是否还留着一点不被任务占满的余地？</strong></p><p>这些问题不必一次答完。留着一问，也正是「游于世」还留有余地的意思。</p><h2 id="全篇收束·不以外物取代生命与理解" tabindex="-1">全篇收束·不以外物取代生命与理解 <a class="header-anchor" href="#全篇收束·不以外物取代生命与理解" aria-label="Permalink to &quot;全篇收束·不以外物取代生命与理解&quot;">​</a></h2><p>《外物》不是只劝人远离身外之物。</p><p>粮食与水可以救急。</p><p>方法与器具可以帮助行动。</p><p>周围土地可以支持立足。</p><p>环境与交往可以促成成长。</p><p>言辞可以帮助理解。</p><p>需要反省的，是这些关系发生倒置：</p><ul><li>用远期承诺替代当前帮助。</li><li>用求名说辞替代广大通达。</li><li>用道德身份掩护实际掠夺。</li><li>用能力出众要求个体保证一切。</li><li>用直接用途删去支持条件。</li><li>用被奖励的行迹证明情感与高洁。</li><li>用固定言辞取代所要领会的意旨。</li></ul><p>因而，一条可供串读的主线是：</p><blockquote><p><strong>不让外在结果、名声、行迹与言辞，反过来垄断生命、行动和理解的尺度。</strong></p></blockquote><p>能够求助，也检查帮助是否适宜。</p><p>能够行动，也承认结果不能全由自身保证。</p><p>能够相顺，也保留自身与必要余地。</p><p>能够言说，也不把所说固定为不可修正的全部。</p><p><strong>篇末不是关闭对话，而是寻找不被言辞拘住的对话者。</strong></p>`,140))])}}});export{L as __pageData,B as default};
